export const BEHAVIORAL_SOCIAL_2_QUIZZES = [
  {
    id:'ps121', cat:'Behavioral & Social Sciences', title:'Types of Psychological Research Studies', diff:'Easy',
    qs:[
      { q:`What is the main goal of an experimental research design in psychology?`, ch:[`To establish cause-and-effect relationships by manipulating variables`,`To describe behavior without manipulation`,`To survey large populations`,`To study one individual in depth`], ans:0, exp:`Experiments involve manipulating an independent variable and observing its effect on a dependent variable while controlling extraneous factors, which allows researchers to draw causal conclusions. Correlational and descriptive methods cannot establish causation.` },
      { q:`In an experiment testing whether a new study app improves test scores, the independent variable is:`, ch:[`The test scores`,`The students' GPA`,`Whether students use the study app`,`The number of participants`], ans:2, exp:`The independent variable is the factor manipulated by the researcher (whether the app is used); the dependent variable is what is measured as an outcome (test scores).` },
      { q:`A researcher observes children playing on a playground without interfering in any way. This is an example of:`, ch:[`A controlled experiment`,`Naturalistic observation`,`A case study`,`A double-blind trial`], ans:1, exp:`Naturalistic observation involves studying behavior in real-world settings without manipulating variables, in contrast to controlled laboratory experiments.` },
      { q:`Which research method involves an in-depth investigation of a single individual or small group, often used to study rare phenomena?`, ch:[`Survey research`,`Cross-sectional study`,`Experimental design`,`Case study`], ans:3, exp:`A case study is an intensive, individual-level analysis (e.g., the famous case of Phineas Gage) that provides rich detail but has limited generalizability compared to larger studies.` },
      { q:`A correlation coefficient of -0.85 indicates:`, ch:[`A weak positive relationship`,`No relationship between variables`,`A strong negative relationship where variables move in opposite directions`,`A strong positive relationship`], ans:2, exp:`Correlation coefficients range from -1 to 1. A magnitude close to 1 indicates a strong relationship, and a negative sign indicates that as one variable increases, the other tends to decrease.` },
      { q:`Why can't correlational studies alone establish causation?`, ch:[`Because a third variable might explain the relationship between two correlated variables`,`Because they always use small sample sizes`,`Because they don't use statistics`,`Because they only apply to animal studies`], ans:0, exp:`The "third-variable problem" means an unmeasured confounding factor could be causing both correlated variables; there is also often ambiguity about which variable, if either, causes the other.` },
      { q:`In a double-blind experimental design:`, ch:[`Only the participants are unaware of group assignment`,`Only the researchers are unaware of group assignment`,`Neither participants nor the researchers administering treatment know who is in each group`,`Both participants and researchers know all assignments`], ans:2, exp:`Double-blind designs reduce bias, including placebo effects and experimenter expectancy effects, by keeping both participants and those administering treatment unaware of group assignment.` },
      { q:`A placebo control group is used in an experiment to:`, ch:[`Increase the overall sample size`,`Eliminate the need for random assignment`,`Test only high-risk populations`,`Control for the psychological effects of receiving treatment, regardless of active ingredient`], ans:3, exp:`Comparing an active treatment group to a placebo group controls for expectation-based effects, helping isolate the true effect of the treatment itself.` },
      { q:`Random assignment in an experiment is important because it:`, ch:[`Ensures the sample represents the population`,`Helps distribute participant characteristics evenly across groups, minimizing pre-existing differences`,`Guarantees a large sample size`,`Eliminates the need for a control group`], ans:1, exp:`Random assignment (distinct from random sampling) tends to equate groups on both known and unknown variables before manipulation occurs, strengthening causal claims.` },
      { q:`A longitudinal study differs from a cross-sectional study in that it:`, ch:[`Follows the same participants over an extended period of time`,`Compares different age groups at a single point in time`,`Uses only qualitative data`,`Cannot include a control group`], ans:0, exp:`Longitudinal studies track the same individuals repeatedly over time, capturing true change but requiring more time and risking participant attrition; cross-sectional studies compare different groups at one time point, which is faster but can confound age with cohort effects.` },
      { q:`An operational definition in psychological research is:`, ch:[`A theoretical explanation of a concept`,`A precise, measurable description of how a variable will be observed or manipulated in a study`,`A researcher's personal opinion about a variable`,`A statistical test used to analyze results`], ans:1, exp:`Operational definitions specify exactly how an abstract construct (e.g., "aggression") will be measured or manipulated in a given study, which allows other researchers to replicate the work.` },
      { q:`Which of the following best describes reliability in psychological measurement?`, ch:[`The extent to which a test measures what it claims to measure`,`The size of the effect found in a study`,`The ethical soundness of a study`,`The consistency of results across repeated measurements`], ans:3, exp:`Reliability refers to consistency or repeatability of a measure, while validity refers to whether a test measures what it is intended to measure; a test can be reliable without being valid.` },
      { q:`A survey researcher who wants results to generalize to a broader population should prioritize:`, ch:[`A convenience sample of friends and family`,`A random sample drawn from the population of interest`,`Interviewing only volunteers who respond enthusiastically`,`Choosing only participants who share the researcher's views`], ans:1, exp:`Random sampling gives every member of the target population an equal chance of being selected, reducing sampling bias and supporting generalizability, unlike convenience or self-selected samples.` },
    ]
  },
  {
    id:'ps122', cat:'Behavioral & Social Sciences', title:'The Nature vs. Nurture Debate', diff:'Easy',
    qs:[
      { q:`The nature vs. nurture debate in psychology concerns the relative contributions of:`, ch:[`Genetics and environment to behavior and traits`,`Conscious and unconscious thought`,`Nature preservation and industrial pollution`,`Classical and operant conditioning`], ans:0, exp:`The debate examines how much of a trait or behavior arises from inherited biological factors ("nature") versus experience and environment ("nurture").` },
      { q:`Twin studies help researchers estimate heritability by comparing:`, ch:[`Identical (monozygotic) twins raised apart with fraternal (dizygotic) twins`,`Only children raised in the same household`,`Adults and children within the same family`,`Twins from different countries only`], ans:0, exp:`Comparing trait similarity in MZ twins (who share 100% of genes) versus DZ twins (who share about 50%), especially when raised apart, helps estimate heritability — the proportion of trait variation within a population attributable to genetic differences.` },
      { q:`Heritability estimates describe:`, ch:[`The exact percentage of an individual's trait caused by genes`,`The proportion of trait variation within a population attributable to genetic differences`,`A guarantee that a trait will be passed to offspring`,`The influence of environment on a single person's development`], ans:1, exp:`Heritability is a population-level statistic, not an individual-level one; it does not indicate how much of any one person's trait is due to genes versus environment.` },
      { q:`Which scenario best illustrates gene-environment interaction?`, ch:[`A gene functions identically regardless of environment`,`A person's genetic predisposition to a disorder only manifests under certain environmental stressors`,`Environment has no effect on gene expression`,`All behavior is purely genetic`], ans:1, exp:`The diathesis-stress model proposes that a genetic predisposition (diathesis) combined with environmental stress can trigger a trait or disorder that might otherwise remain dormant.` },
      { q:`Epigenetics refers to:`, ch:[`Changes in the underlying DNA sequence itself`,`Chemical modifications that affect gene expression without altering the underlying DNA sequence`,`The complete elimination of genetic influence on behavior`,`A form of natural selection`], ans:1, exp:`Epigenetic marks, such as DNA methylation, can be influenced by experience and environment and can turn genes on or off without changing the DNA code itself; some marks can even be passed to offspring.` },
      { q:`Adoption studies are useful for studying nature vs. nurture because they allow researchers to:`, ch:[`Ignore genetic contributions entirely`,`Separate genetic influence (biological parents) from environmental influence (adoptive parents)`,`Study only children raised by both biological parents`,`Eliminate the need for control groups`], ans:1, exp:`By comparing adopted children to both their biological and adoptive parents, researchers can partially disentangle genetic and environmental contributions to a trait.` },
      { q:`The modern scientific consensus on nature vs. nurture is that:`, ch:[`Nature completely determines behavior`,`Nurture completely determines behavior`,`Most traits arise from a complex interaction of genetic and environmental factors`,`Genes and environment operate entirely independently of each other`], ans:2, exp:`Contemporary behavioral genetics generally rejects strict either/or framing, instead emphasizing that genes and environment interact dynamically to shape most psychological traits.` },
      { q:`Which of the following is an example of an environmental (nurture) influence on development?`, ch:[`Eye color`,`Blood type`,`Parenting style and peer relationships`,`Height determined solely by parental height`], ans:2, exp:`Parenting style and peer relationships are external, experiential influences, in contrast to largely genetically determined physical traits like eye color and blood type.` },
      { q:`The concept of "canalization" in development refers to:`, ch:[`Traits that are highly susceptible to environmental influence`,`Traits that develop consistently across a wide range of environments due to strong genetic programming`,`Environmental factors that change genetic code`,`A statistical method for calculating heritability`], ans:1, exp:`Canalized traits, such as basic motor milestones, are buffered against environmental variation and develop similarly across diverse conditions, whereas less canalized traits are more environmentally malleable.` },
      { q:`A key criticism of early "nature vs. nurture" framing is that it:`, ch:[`Was too focused on environment`,`Falsely implies genes and environment are separable, competing forces rather than interacting influences`,`Ignored genetics completely`,`Was only ever applied to physical traits`], ans:1, exp:`Many modern researchers view the dichotomy as misleading because genes and environment continuously interact and influence each other rather than acting as independent, competing forces.` },
      { q:`Which research design compares family members with varying degrees of genetic relatedness to estimate genetic contributions to a trait?`, ch:[`Case study`,`Behavioral genetics / family study`,`Cross-sectional study`,`Naturalistic observation`], ans:1, exp:`Family and twin studies compare individuals with different degrees of shared genetics (e.g., siblings, twins, parents) to help estimate the genetic contribution to a trait.` },
      { q:`Prenatal environment, including maternal nutrition, stress, and substance exposure, demonstrates that "nurture" influences begin:`, ch:[`Only after birth`,`Only during adolescence`,`Before birth, in utero`,`Only in adulthood`], ans:2, exp:`Prenatal conditions can measurably affect fetal brain development and later outcomes, showing that environmental influence starts before birth, not just after.` },
      { q:`Sir Francis Galton, who coined the phrase "nature versus nurture," is also known for:`, ch:[`Founding modern behaviorism`,`Promoting eugenics based on the belief that intelligence was primarily hereditary`,`Developing the theory of operant conditioning`,`Discovering classical conditioning`], ans:1, exp:`Galton's eugenics advocacy is now widely regarded as scientifically flawed and ethically troubling, and is taught today as a historical cautionary example of overemphasizing genetic determinism.` },
    ]
  },
  {
    id:'ps123', cat:'Behavioral & Social Sciences', title:'Humanistic Psychology: Maslow & Rogers', diff:'Medium',
    qs:[
      { q:`Humanistic psychology emerged largely as a reaction against which two dominant schools of thought?`, ch:[`Behaviorism and psychoanalysis`,`Cognitive and biological psychology`,`Structuralism and functionalism`,`Sociology and anthropology`], ans:0, exp:`Humanistic psychology, associated with Maslow and Rogers, arose as a "third force," criticizing behaviorism's focus on observable behavior and determinism and psychoanalysis's focus on unconscious conflict, instead emphasizing free will, personal growth, and self-actualization.` },
      { q:`In Maslow's hierarchy of needs, which need must generally be reasonably satisfied first?`, ch:[`Self-actualization`,`Esteem`,`Physiological needs (food, water, sleep)`,`Belongingness and love`], ans:2, exp:`Maslow's pyramid orders needs from most basic to highest: physiological, safety, love/belonging, esteem, and self-actualization; lower needs generally must be reasonably met before higher needs become strongly motivating.` },
      { q:`Self-actualization, at the top of Maslow's hierarchy, refers to:`, ch:[`Meeting basic survival needs`,`Realizing one's full potential and becoming the most complete version of oneself`,`Seeking approval from others`,`Avoiding physical danger`], ans:1, exp:`Self-actualization is the drive to fulfill one's unique potential and pursue personal growth, meaning, and creativity.` },
      { q:`Carl Rogers' person-centered therapy emphasizes which three core therapist conditions?`, ch:[`Diagnosis, medication, and behavior modification`,`Unconditional positive regard, empathy, and genuineness (congruence)`,`Free association and dream analysis`,`Systematic desensitization and reinforcement`], ans:1, exp:`Rogers proposed that therapeutic change occurs when the therapist provides unconditional positive regard, empathic understanding, and genuineness, creating conditions for the client's innate growth tendency to unfold.` },
      { q:`According to Rogers, "unconditional positive regard" means:`, ch:[`Praising a client only when they behave correctly`,`Accepting and valuing a person regardless of what they say or do`,`Ignoring a client's negative behaviors entirely`,`Offering material rewards for desired behavior`], ans:1, exp:`Unconditional positive regard is nonjudgmental acceptance of the client as a person, which Rogers believed helps reduce defensiveness and supports growth.` },
      { q:`Rogers used the term "congruence" to describe:`, ch:[`A mismatch between one's self-concept and actual experience`,`Alignment between one's self-concept and one's actual lived experience and feelings`,`A stage of cognitive development`,`A type of defense mechanism`], ans:1, exp:`Incongruence, a mismatch between self-image and actual experience, causes anxiety and distress; therapy aims to help clients achieve greater congruence between their real and ideal selves.` },
      { q:`Maslow developed his hierarchy of needs partly by studying:`, ch:[`Patients with severe mental illness`,`Psychologically healthy, high-functioning individuals he considered self-actualized`,`Laboratory rats`,`Only young children`], ans:1, exp:`Maslow studied exemplary historical figures he believed exhibited self-actualization, a notable departure from the era's dominant focus on pathology.` },
      { q:`A common criticism of Maslow's hierarchy of needs is that:`, ch:[`It has strong, consistent cross-cultural research support`,`It is difficult to test scientifically, and the rigid ordering of needs doesn't always hold across individuals and cultures`,`It focuses too heavily on biological needs alone`,`It was derived entirely from animal studies`], ans:1, exp:`Critics note that people sometimes pursue higher needs (e.g., meaning, belonging) even when lower needs are unmet, and that the hierarchy's rigid stage-like structure lacks strong empirical support.` },
      { q:`The humanistic emphasis on "free will" contrasts most directly with which perspective?`, ch:[`Behaviorism's emphasis on environmental determinism of behavior`,`Cognitive psychology's study of memory`,`Developmental psychology's study of aging`,`Sociology's study of institutions`], ans:0, exp:`Behaviorists like Skinner viewed behavior as largely shaped by environmental reinforcement history, while humanists emphasized personal choice and self-directed growth.` },
      { q:`In Rogers' theory, the "real self" and "ideal self" refer to:`, ch:[`Two unrelated personality traits`,`One's actual self-concept versus who one aspires to be`,`Conscious and unconscious minds`,`Genetic and environmental influences`], ans:1, exp:`A large gap between one's real self and ideal self is associated with lower self-esteem and greater psychological distress; therapy aims to narrow this gap.` },
      { q:`Which statement best reflects the humanistic view of human nature?`, ch:[`Humans are fundamentally driven by unconscious sexual and aggressive drives`,`Humans are essentially good and motivated toward growth and self-actualization when conditions allow`,`Human behavior is entirely shaped by reinforcement history`,`Personality is fixed at birth and unchangeable`], ans:1, exp:`Humanistic psychology holds an optimistic view of human nature, assuming an innate tendency toward growth and self-fulfillment when the right conditions (such as acceptance and support) are present.` },
      { q:`Client-centered (person-centered) therapy differs from traditional psychoanalysis in that the therapist:`, ch:[`Interprets the client's unconscious conflicts`,`Acts as a non-directive facilitator who trusts the client to find their own answers`,`Prescribes medication to manage symptoms`,`Uses systematic reinforcement schedules`], ans:1, exp:`Rather than interpreting hidden conflicts, the person-centered therapist creates a supportive, non-judgmental environment and trusts the client's own capacity for insight and growth.` },
      { q:`Which of the following is a criticism commonly raised against humanistic psychology as a whole?`, ch:[`It is overly focused on biological determinism`,`Its concepts, such as self-actualization, can be vague and difficult to operationalize and test empirically`,`It denies the existence of free will`,`It relies exclusively on animal experiments`], ans:1, exp:`Critics argue that humanistic concepts are often difficult to define precisely and measure scientifically, limiting rigorous empirical testing compared to more behaviorally or biologically grounded approaches.` },
    ]
  },
  {
    id:'ps124', cat:'Behavioral & Social Sciences', title:'Everyday Cognitive Biases & Heuristics', diff:'Medium',
    qs:[
      { q:`The availability heuristic leads people to judge the likelihood of an event based on:`, ch:[`Formal statistical calculations`,`How easily relevant examples come to mind`,`Random guessing`,`The size of the sample studied`], ans:1, exp:`Because vivid, memorable, or recent events are more easily recalled, people often overestimate their frequency — for example, overestimating the risk of a shark attack after heavy media coverage, even though actual rates are low.` },
      { q:`The representativeness heuristic can lead to errors because people:`, ch:[`Ignore all similarities between cases`,`Judge probability based on how similar something is to a prototype, ignoring statistical base rates`,`Only use official statistics`,`Never rely on stereotypes`], ans:1, exp:`Relying on how closely something matches a mental prototype can cause people to neglect actual population base rates, leading to systematic misjudgments of probability.` },
      { q:`Anchoring bias occurs when:`, ch:[`People completely ignore initial information`,`An initial piece of information disproportionately influences subsequent judgments, even if arbitrary`,`People randomly select answers with no pattern`,`Decisions are made without any reference point`], ans:1, exp:`In a classic demonstration, participants shown a high random number before estimating a quantity gave higher estimates than those shown a low number, showing that irrelevant initial anchors skew judgment.` },
      { q:`Confirmation bias refers to the tendency to:`, ch:[`Seek out and favor information that confirms existing beliefs while discounting contradictory evidence`,`Change one's mind easily when presented with new facts`,`Remember failures more than successes`,`Distrust all authority figures`], ans:0, exp:`Confirmation bias describes people's tendency to notice, seek, and remember information that supports what they already believe, while dismissing or downplaying disconfirming evidence.` },
      { q:`The sunk cost fallacy describes the tendency to:`, ch:[`Avoid any investment of time or money`,`Continue investing in a decision because of resources already spent, even when it's no longer rational`,`Always choose the cheapest option`,`Ignore past investments entirely`], ans:1, exp:`People often keep pursuing a failing course of action (like finishing a bad movie or an unprofitable project) because of what they have already invested, rather than basing the decision on future costs and benefits alone.` },
      { q:`Hindsight bias is best described as:`, ch:[`The inability to remember past events`,`The tendency to see past events as having been predictable after they have already occurred ('I knew it all along')`,`Overestimating future risks`,`Underestimating the importance of the past`], ans:1, exp:`After learning an outcome, people often overestimate how predictable that outcome actually was beforehand, distorting later judgments of past decision quality.` },
      { q:`Overconfidence bias in decision-making refers to:`, ch:[`Excessive doubt in one's own judgments`,`People's tendency to have greater confidence in their judgments and abilities than is objectively warranted`,`A bias that only affects experts, not novices`,`A bias that only appears in group settings`], ans:1, exp:`Overconfidence is a well-documented and widespread bias in which people's subjective certainty exceeds their actual accuracy, affecting both novices and experts across many domains.` },
      { q:`Base rate neglect occurs when people:`, ch:[`Overemphasize the general prevalence (base rate) of an event in the population`,`Ignore statistical base-rate information in favor of specific case details`,`Only use statistical information to make judgments`,`Refuse to make any judgment without data`], ans:1, exp:`A classic example is judging someone as more likely to be a librarian than a farmer based on a stereotypical personality description, while ignoring that farmers vastly outnumber librarians in the population.` },
      { q:`Illusory correlation refers to:`, ch:[`A correlation coefficient of exactly 1.0`,`Perceiving a relationship between two variables that does not actually exist, or is weaker than assumed`,`Two variables that are perfectly correlated`,`A statistical technique for controlling confounds`], ans:1, exp:`People sometimes perceive a systematic relationship between two things (such as a rare event and a particular group) based on memorable but unrepresentative instances, even when no real statistical relationship exists.` },
      { q:`Optimism bias leads people to:`, ch:[`Overestimate the likelihood of negative events happening to them`,`Underestimate their own likelihood of experiencing negative events relative to others`,`Have no expectations about the future`,`Always plan for worst-case scenarios`], ans:1, exp:`Most people tend to believe they are less likely than their peers to experience negative events, such as illness or accidents, a pattern known as optimism bias or "unrealistic optimism."` },
      { q:`The Dunning-Kruger effect describes a pattern in which:`, ch:[`Highly skilled individuals consistently underestimate their competence`,`People with low ability at a task tend to overestimate their competence due to limited insight into their own errors`,`Experts always accurately assess their own skill level`,`Confidence and competence are always perfectly correlated`], ans:1, exp:`Individuals with low skill in a domain often lack the very expertise needed to recognize their own mistakes, leading them to overestimate their ability relative to more skilled peers.` },
      { q:`Which strategy is generally most effective for reducing the impact of cognitive biases in decision-making?`, ch:[`Relying solely on gut instinct`,`Deliberately seeking disconfirming evidence and considering alternative explanations`,`Making decisions as quickly as possible`,`Avoiding all statistical information`], ans:1, exp:`Actively considering evidence that contradicts one's initial view, and deliberately entertaining alternative explanations, is a well-supported "debiasing" technique that can counteract confirmation bias and overconfidence.` },
      { q:`The "gambler's fallacy" is the mistaken belief that:`, ch:[`Future probabilities are influenced by past independent random events (e.g., a coin is 'due' for tails after several heads)`,`Random events are impossible to predict`,`All games of chance are rigged`,`Past outcomes have no relevance to anything`], ans:0, exp:`Since coin flips (and similar independent random events) have no memory, each flip retains the same probability regardless of prior outcomes; believing a streak makes an opposite outcome "due" is a statistical error.` },
    ]
  },
  {
    id:'ps125', cat:'Behavioral & Social Sciences', title:'Memory Strategies & Study Techniques', diff:'Easy',
    qs:[
      { q:`The "spacing effect" in learning research shows that:`, ch:[`Cramming all study time into one long session produces the best long-term retention`,`Spreading study sessions out over time leads to better long-term retention than massed practice (cramming)`,`Studying only right before a test is most effective`,`Spacing has no effect on memory`], ans:1, exp:`Distributed practice across multiple sessions over time consistently produces stronger long-term retention than massing the same amount of study time into one cramming session.` },
      { q:`Retrieval practice, such as self-testing with flashcards, improves learning primarily because:`, ch:[`It simply re-exposes students to the material without effort`,`Actively recalling information strengthens memory more effectively than passive re-reading`,`It eliminates the need for further studying`,`It only works for rote memorization of simple lists`], ans:1, exp:`The effort of actively retrieving information from memory strengthens the memory trace more than passively re-reading the same material, a robust finding known as the testing effect.` },
      { q:`The "testing effect" refers to the finding that:`, ch:[`Taking practice tests impairs long-term memory`,`Taking a test on material, even without feedback, enhances long-term retention compared to simply restudying`,`Tests only measure short-term memory`,`Frequent testing increases anxiety without any learning benefit`], ans:1, exp:`Numerous studies show that the act of retrieving information during a test itself strengthens memory, often producing better long-term retention than an equivalent amount of restudying.` },
      { q:`Elaborative rehearsal improves memory by:`, ch:[`Simply repeating information verbatim`,`Connecting new information to existing knowledge and giving it meaning`,`Avoiding any connections to prior knowledge`,`Reducing the amount of information studied`], ans:1, exp:`Elaborative rehearsal involves deeply processing information by linking it to things already known, which produces stronger, more durable memories than shallow, rote repetition (maintenance rehearsal).` },
      { q:`The method of loci is a mnemonic technique that involves:`, ch:[`Repeating information in a monotone voice`,`Mentally associating items to be remembered with specific locations along a familiar path`,`Writing information down as many times as possible`,`Studying only in a single fixed location`], ans:1, exp:`This ancient memory technique uses a familiar spatial route, mentally "placing" items to remember at specific points along the path, leveraging strong visual-spatial memory.` },
      { q:`Which of the following is an example of "chunking" as a memory strategy?`, ch:[`Memorizing a 10-digit phone number as ten separate random digits`,`Grouping a string of numbers into smaller, meaningful units, such as an area code plus a prefix`,`Reading a chapter only once`,`Ignoring patterns in information`], ans:1, exp:`Chunking groups individual pieces of information into larger, more meaningful units, reducing the load on working memory and making information easier to remember.` },
      { q:`According to research on study habits, which of the following is generally LESS effective than most students believe?`, ch:[`Practice testing`,`Distributed practice`,`Highlighting and re-reading text passively`,`Interleaving different topics`], ans:2, exp:`Reviews of study techniques (e.g., Dunlosky et al.) rate highlighting and rereading as low-utility techniques compared to retrieval practice and spaced practice, despite their popularity among students.` },
      { q:`Interleaving, as a study technique, involves:`, ch:[`Studying one topic exhaustively before moving to the next`,`Mixing different topics or problem types within a single study session`,`Avoiding all variety in practice problems`,`Studying only right before exams`], ans:1, exp:`Interleaving mixes related but distinct topics or problem types during practice, which research shows can improve the ability to discriminate between concepts and apply the right strategy, compared to blocked practice.` },
      { q:`Sleep plays an important role in memory consolidation primarily by:`, ch:[`Erasing unimportant memories only`,`Helping stabilize and strengthen newly formed memories, especially during certain sleep stages`,`Having no measurable effect on learning`,`Only benefiting procedural memory, not declarative memory`], ans:1, exp:`Sleep, particularly slow-wave and REM stages, supports the consolidation of both declarative (fact-based) and procedural (skill-based) memories formed during the day.` },
      { q:`The "generation effect" in memory research suggests that:`, ch:[`Information is better remembered when it is passively read`,`Information is better remembered when learners generate it themselves rather than simply reading it`,`Older generations have better memory than younger ones`,`Generating incorrect answers has no learning value`], ans:1, exp:`When learners actively produce an answer or piece of information themselves, rather than just reading it, they tend to remember it better than passively received material.` },
      { q:`Dual coding theory suggests that learning is enhanced when:`, ch:[`Information is presented in only verbal form`,`Information is presented through both verbal and visual channels`,`Learners avoid using any visual aids`,`Only auditory information is used`], ans:1, exp:`Dual coding theory proposes that combining verbal and visual representations of information creates two distinct memory traces, improving recall compared to a single-channel presentation.` },
      { q:`Which of the following best describes "overlearning" as a study strategy?`, ch:[`Stopping practice the moment material is first correctly recalled`,`Continuing to practice material beyond the point of initial mastery to strengthen retention`,`Studying material only once`,`Avoiding review sessions entirely`], ans:1, exp:`Overlearning — continuing practice after material is first mastered — has been shown to improve retention, though returns diminish with excessive additional practice.` },
      { q:`A student who studies math problems in a quiet library, a noisy cafe, and outdoors is applying which principle to potentially improve retention?`, ch:[`State-dependent learning exclusively`,`Context variability, which can make memory more flexible and less dependent on one specific environment`,`Cramming`,`Rote memorization`], ans:1, exp:`Varying the study environment (context variability) can help make retrieval less dependent on any single context, potentially improving recall in a variety of situations, such as a test venue different from where studying occurred.` },
    ]
  },
  {
    id:'ps126', cat:'Behavioral & Social Sciences', title:'Emotional Intelligence', diff:'Easy',
    qs:[
      { q:`Emotional intelligence (EI), as popularized by Daniel Goleman, generally refers to:`, ch:[`A person's IQ score on standardized tests`,`The ability to perceive, understand, manage, and use emotions effectively in oneself and others`,`A fixed, unchangeable personality trait`,`The number of friends a person has`], ans:1, exp:`Emotional intelligence describes a set of abilities related to recognizing and regulating one's own emotions and understanding and responding well to others' emotions.` },
      { q:`Which of the following is generally considered a core component of emotional intelligence?`, ch:[`Self-awareness — recognizing and understanding one's own emotions`,`Physical strength`,`Rote memorization skill`,`Reaction time`], ans:0, exp:`Self-awareness, the ability to recognize and understand one's own emotional states, is widely considered a foundational component of emotional intelligence models.` },
      { q:`"Self-regulation" in emotional intelligence refers to:`, ch:[`Suppressing all emotional expression permanently`,`The ability to manage and control one's emotional responses and impulses appropriately`,`Ignoring the emotions of others`,`Acting purely on impulse`], ans:1, exp:`Self-regulation involves managing disruptive emotions and impulses in a way that supports thoughtful, adaptive responses rather than either suppression or unchecked reactivity.` },
      { q:`Empathy, as a component of emotional intelligence, is best defined as:`, ch:[`Agreeing with everything another person says`,`The capacity to understand and share the feelings of another person`,`Avoiding emotional situations`,`A synonym for sympathy with no distinction`], ans:1, exp:`Empathy involves recognizing and understanding another person's emotional experience, which supports effective communication and relationship-building.` },
      { q:`Social skills, within the emotional intelligence framework, primarily involve:`, ch:[`Managing relationships and building rapport to move people in desired directions`,`Avoiding all social interaction`,`Memorizing facts about people`,`Suppressing one's own needs entirely`], ans:0, exp:`Social skills refer to the ability to build relationships, communicate effectively, and influence and collaborate with others productively.` },
      { q:`Which scenario best illustrates high emotional intelligence?`, ch:[`Reacting to criticism with immediate anger and shouting`,`Recognizing frustration rising during a disagreement and pausing to respond thoughtfully rather than react impulsively`,`Ignoring how a coworker feels to focus solely on tasks`,`Avoiding any feedback conversations altogether`], ans:1, exp:`Noticing one's own rising emotion and choosing a measured response rather than an impulsive reaction reflects both self-awareness and self-regulation, key EI skills.` },
      { q:`Research on emotional intelligence and workplace success suggests that:`, ch:[`EI is irrelevant to job performance`,`EI often contributes meaningfully to leadership effectiveness and teamwork, alongside cognitive ability`,`Only IQ predicts job success`,`EI cannot be developed or improved`], ans:1, exp:`Studies link higher emotional intelligence to better leadership, teamwork, and interpersonal effectiveness at work, complementing (not replacing) the role of cognitive ability.` },
      { q:`Unlike traditional IQ, emotional intelligence is generally considered to be:`, ch:[`Completely fixed at birth with no room for growth`,`Something that can be developed and improved with practice and training over time`,`Unrelated to personal relationships`,`Only relevant during childhood`], ans:1, exp:`Most researchers and practitioners view emotional intelligence skills as learnable and improvable through deliberate practice, training, and feedback across the lifespan.` },
      { q:`Motivation, as a component of emotional intelligence, refers to:`, ch:[`An external reward system only`,`An internal drive to pursue goals with energy and persistence, independent of external rewards`,`Avoiding all challenges`,`Relying entirely on others for encouragement`], ans:1, exp:`In Goleman's model, motivation reflects an intrinsic passion to pursue goals for reasons beyond money or status, including persistence in the face of setbacks.` },
      { q:`A person with low emotional intelligence in a conflict is most likely to:`, ch:[`Recognize their own triggers and de-escalate calmly`,`Struggle to recognize how their words affect others and escalate the conflict`,`Automatically resolve the disagreement`,`Have low cognitive intelligence as well`], ans:1, exp:`Low emotional intelligence is associated with difficulty recognizing the emotional impact of one's own behavior, which can inadvertently escalate interpersonal conflict.` },
      { q:`Which of the following is an example of effectively managing someone else's emotions, a component of EI?`, ch:[`Ignoring a distressed friend`,`Calming a nervous teammate before a presentation with reassurance and encouragement`,`Telling someone to just "get over it"`,`Avoiding the conversation entirely`], ans:1, exp:`Relationship management, a core EI skill, involves helping others regulate their emotions constructively, such as offering reassurance to reduce a teammate's anxiety.` },
      { q:`The Mayer-Salovey-Caruso model conceptualizes emotional intelligence primarily as:`, ch:[`A set of learned social rules only`,`A set of mental abilities involving perceiving, using, understanding, and managing emotions`,`A personality trait unrelated to cognition`,`A measure of physical fitness`], ans:1, exp:`This influential "ability model" of EI frames it as a set of cognitive-emotional abilities, distinct from purely personality-based or trait-based conceptions.` },
      { q:`Emotional intelligence is best understood as complementary to, rather than a replacement for:`, ch:[`Physical health`,`Cognitive intelligence (IQ) and technical skills`,`Sleep`,`Genetics`], ans:1, exp:`Most researchers view emotional intelligence as working alongside cognitive ability and technical competence, not as a substitute for either, in predicting overall success.` },
    ]
  },
  {
    id:'ps127', cat:'Behavioral & Social Sciences', title:'Resilience & Grit', diff:'Easy',
    qs:[
      { q:`Psychological resilience is best defined as:`, ch:[`The complete absence of stress or adversity in one's life`,`The capacity to adapt well and recover functioning in the face of adversity, trauma, or significant stress`,`A fixed personality trait present from birth`,`Avoiding all challenges to prevent failure`], ans:1, exp:`Resilience refers to the ability to adapt and "bounce back" after hardship, not the absence of hardship itself; it can be strengthened through experience, support, and coping skills.` },
      { q:`Angela Duckworth's concept of "grit" refers to:`, ch:[`Natural talent alone`,`Passion and sustained perseverance toward long-term goals`,`Avoiding difficult tasks`,`Short bursts of high-intensity effort only`], ans:1, exp:`Grit describes sustained passion and persistent effort directed at long-term goals, distinct from raw talent or brief motivation spikes.` },
      { q:`Research on resilient children, such as Emmy Werner's longitudinal studies, found that a key protective factor was often:`, ch:[`Complete absence of childhood adversity`,`At least one stable, caring relationship with a supportive adult`,`Higher intelligence alone regardless of relationships`,`Financial wealth exclusively`], ans:1, exp:`Werner's Kauai longitudinal study found that having at least one consistent, caring adult relationship was strongly associated with resilience among children facing significant adversity.` },
      { q:`A "growth mindset," as described by Carol Dweck, involves believing that:`, ch:[`Abilities are fixed traits that cannot change`,`Abilities and intelligence can be developed through effort, strategy, and learning`,`Failure should always be avoided`,`Only some people are capable of improvement`], ans:1, exp:`A growth mindset is the belief that abilities can be developed through dedication and effort, in contrast to a "fixed mindset" that views abilities as static traits.` },
      { q:`Which coping strategy is generally associated with greater resilience following setbacks?`, ch:[`Avoiding thinking about the problem indefinitely`,`Reframing a setback as a learning opportunity (cognitive reappraisal)`,`Blaming oneself entirely for uncontrollable events`,`Withdrawing from all social support`], ans:1, exp:`Cognitive reappraisal — reframing a stressful event in a more constructive light — is a well-supported adaptive coping strategy linked to greater resilience.` },
      { q:`Grit, as measured by Duckworth's Grit Scale, is composed of two main facets:`, ch:[`Intelligence and creativity`,`Consistency of interests and perseverance of effort over time`,`Social skill and physical strength`,`Luck and opportunity`], ans:1, exp:`The Grit Scale assesses both how consistently a person maintains interest in long-term goals and how persistently they work toward them despite obstacles.` },
      { q:`Which of the following is an example of building resilience through social support?`, ch:[`Isolating oneself after a difficult event`,`Seeking help and connection from friends, family, or community during hardship`,`Refusing to discuss problems with anyone`,`Relying only on oneself in all circumstances`], ans:1, exp:`Strong social support networks are one of the most consistently identified protective factors that help people cope with and recover from adversity.` },
      { q:`A "fixed mindset," in contrast to a growth mindset, tends to lead people to:`, ch:[`Embrace challenges as opportunities to grow`,`Avoid challenges for fear of failure, since ability is seen as unchangeable`,`Persist longer in the face of setbacks`,`View effort as the primary path to mastery`], ans:1, exp:`Those with a fixed mindset tend to avoid challenges that might reveal a perceived lack of innate ability, since they view talent as largely unchangeable.` },
      { q:`Post-traumatic growth refers to:`, ch:[`The inevitability of permanent psychological damage after trauma`,`Positive psychological change that some individuals experience as a result of struggling with highly challenging life circumstances`,`A rare disorder unrelated to trauma`,`The absence of any emotional response to trauma`], ans:1, exp:`Post-traumatic growth describes positive personal transformation — such as a deepened sense of meaning or stronger relationships — that some people experience after struggling through trauma, distinct from resilience itself.` },
      { q:`Which factor has research generally shown to undermine resilience-building efforts?`, ch:[`Chronic, unsupported exposure to overwhelming stress without any coping resources`,`Having a strong support network`,`Practicing adaptive coping strategies`,`Developing a sense of purpose`], ans:0, exp:`Prolonged, overwhelming stress without adequate coping resources or support tends to erode resilience rather than build it, in contrast to manageable challenges paired with support.` },
      { q:`Critics of the "grit" concept have argued that overemphasizing individual perseverance risks:`, ch:[`Fully explaining success while ignoring the role of socioeconomic and structural barriers`,`Being completely disproven by all available research`,`Applying only to athletes`,`Having no relationship to long-term achievement`], ans:0, exp:`Some researchers caution that focusing heavily on individual grit can understate how structural factors, such as access to resources and opportunity, also shape outcomes.` },
      { q:`Self-efficacy, a concept closely related to resilience, refers to:`, ch:[`A belief in one's own capability to execute behaviors necessary to produce desired outcomes`,`A permanent trait unaffected by past experience`,`The same concept as self-esteem`,`An external locus of control`], ans:0, exp:`Self-efficacy (Bandura) is a task-specific belief in one's own competence, which is distinct from general self-esteem and can be strengthened through mastery experiences.` },
      { q:`Which practice is commonly recommended to help build resilience over time?`, ch:[`Avoiding reflection on past challenges`,`Developing realistic goals and taking decisive action toward them`,`Suppressing all difficult emotions permanently`,`Relying exclusively on luck`], ans:1, exp:`Setting achievable goals and taking proactive steps toward them is a widely recommended resilience-building strategy, alongside maintaining social connections and adaptive coping.` },
    ]
  },
  {
    id:'ps128', cat:'Behavioral & Social Sciences', title:'Circadian Rhythms & Sleep Hygiene', diff:'Medium',
    qs:[
      { q:`The circadian rhythm is best described as:`, ch:[`A random pattern of sleep and wakefulness`,`An internally generated, roughly 24-hour biological cycle regulating sleep-wake patterns and other physiological processes`,`A rhythm found only in humans`,`A pattern entirely controlled by external light with no internal clock`], ans:1, exp:`The circadian rhythm is an endogenous, approximately 24-hour cycle that regulates sleep-wake timing, hormone release, body temperature, and other processes, though it is also influenced and synchronized by external cues like light.` },
      { q:`The primary biological "master clock" regulating circadian rhythms in mammals is located in the:`, ch:[`Cerebellum`,`Suprachiasmatic nucleus (SCN) of the hypothalamus`,`Amygdala`,`Medulla oblongata`], ans:1, exp:`The SCN, a small structure in the hypothalamus, receives direct input from the eyes and coordinates the body's master circadian timing signal.` },
      { q:`Light exposure influences circadian rhythms primarily through its effect on:`, ch:[`Adrenaline production only`,`Melatonin secretion from the pineal gland, which is suppressed by light and released in darkness`,`Blood pressure regulation`,`Digestive enzyme release`], ans:1, exp:`Light exposure suppresses melatonin production, while darkness promotes its release, helping synchronize the body's internal clock with the external day-night cycle.` },
      { q:`"Sleep hygiene" refers to:`, ch:[`Literal physical cleanliness of bedding only`,`A set of behavioral and environmental practices that promote consistent, good-quality sleep`,`A medical treatment for insomnia requiring medication`,`A term describing dream content`], ans:1, exp:`Sleep hygiene encompasses habits such as consistent sleep schedules, a comfortable sleep environment, and avoiding stimulants before bed, all aimed at supporting healthy sleep.` },
      { q:`Which of the following is a recommended sleep hygiene practice?`, ch:[`Using bright screens in bed right before sleep`,`Keeping a consistent sleep and wake schedule, even on weekends`,`Consuming caffeine in the evening`,`Taking long naps late in the afternoon`], ans:1, exp:`A consistent sleep-wake schedule helps stabilize the circadian rhythm; screens, evening caffeine, and long late naps are generally discouraged as they can disrupt sleep onset and quality.` },
      { q:`Blue light from phone and computer screens before bedtime can disrupt sleep primarily by:`, ch:[`Increasing melatonin production`,`Suppressing melatonin production and delaying the onset of sleepiness`,`Having no effect on the circadian system`,`Only affecting people over age 60`], ans:1, exp:`Blue-enriched light is particularly effective at suppressing melatonin release, which can delay the body's natural transition into sleepiness.` },
      { q:`"Jet lag" occurs when:`, ch:[`A person's internal circadian clock is misaligned with the external light-dark cycle of a new time zone`,`Someone sleeps too much in their home time zone`,`The SCN stops functioning permanently`,`Melatonin is overproduced chronically`], ans:0, exp:`Jet lag results from a temporary mismatch between the body's internal circadian timing and the light-dark cycle of a new time zone after rapid travel across zones.` },
      { q:`Shift workers who regularly work overnight often experience health problems partly because:`, ch:[`Their circadian rhythms are optimized for nighttime alertness`,`Their behavioral schedule conflicts with their internal circadian rhythm, which remains partly tuned to the light-dark cycle`,`Melatonin has no relevance to shift work`,`They sleep exactly the recommended hours regardless of timing`], ans:1, exp:`Working against one's internal circadian timing creates chronic misalignment, which has been linked to sleep problems and other health risks in shift workers.` },
      { q:`Which age-related change in circadian rhythm timing is well documented?`, ch:[`Adolescents' circadian rhythms often shift later, making early school start times more difficult biologically`,`Young children naturally prefer to stay up much later than teenagers`,`Older adults typically shift toward much later sleep and wake times`,`Circadian rhythms do not change across the lifespan`], ans:0, exp:`During adolescence, the circadian rhythm typically shifts to a later phase, making early wake times biologically harder, which has informed debates about school start times.` },
      { q:`Consistent exposure to natural light in the morning is recommended for good sleep hygiene because it:`, ch:[`Delays the body's internal clock indefinitely`,`Helps anchor and synchronize the circadian rhythm to the external day-night cycle`,`Increases evening melatonin release immediately`,`Has no effect on alertness`], ans:1, exp:`Morning light exposure helps set and stabilize the circadian clock, reinforcing daytime alertness and appropriately timed evening melatonin release.` },
      { q:`Which of the following best describes "sleep debt"?`, ch:[`A financial cost associated with sleep disorders`,`The cumulative effect of not getting enough sleep over multiple nights`,`A single night of good sleep`,`A permanent and irreversible condition`], ans:1, exp:`Sleep debt accumulates when a person consistently sleeps less than their biological need, and it can be partly, though not perfectly, reduced through subsequent extra sleep.` },
      { q:`Napping recommendations for good sleep hygiene generally suggest that naps should be:`, ch:[`As long as possible, taken any time of day`,`Short, around 20-30 minutes, and earlier in the day to avoid interfering with nighttime sleep`,`Avoided entirely under all circumstances`,`Taken right before bedtime for best effect`], ans:1, exp:`Short, early-day naps are generally recommended to boost alertness without producing sleep inertia or interfering with the ability to fall asleep at night.` },
      { q:`Caffeine can disrupt sleep because it:`, ch:[`Directly increases melatonin production`,`Blocks adenosine receptors, reducing the sleep pressure that normally builds throughout the day`,`Has no measurable half-life in the body`,`Only affects people who rarely consume it`], ans:1, exp:`Caffeine blocks adenosine receptors in the brain, counteracting the buildup of adenosine-related "sleep pressure" that normally promotes sleepiness as the day progresses.` },
    ]
  },
  {
    id:'ps129', cat:'Behavioral & Social Sciences', title:'Social Institutions: An Overview', diff:'Easy',
    qs:[
      { q:`In sociology, a social institution is best defined as:`, ch:[`A single individual's personal habits`,`An established, organized system of social behavior with a recognized purpose that meets basic societal needs`,`A random, temporary social gathering`,`A government building`], ans:1, exp:`Social institutions, such as family, education, and government, are enduring, patterned systems of social relationships organized to meet fundamental needs of society.` },
      { q:`Which of the following is commonly identified as a major social institution?`, ch:[`The family`,`A single conversation between friends`,`A momentary trend`,`An individual's personal opinion`], ans:0, exp:`The family is one of the most widely recognized social institutions, alongside education, religion, government, and the economy.` },
      { q:`The economy, as a social institution, primarily addresses society's need to:`, ch:[`Produce, distribute, and consume goods and services`,`Regulate emotional expression`,`Provide religious guidance`,`Educate young children exclusively`], ans:0, exp:`The economy is the institution organized around the production, distribution, and consumption of goods and services within a society.` },
      { q:`Functionalist theory views social institutions as existing primarily to:`, ch:[`Create conflict between social classes`,`Perform functions necessary to maintain social order and stability`,`Serve no purpose in society`,`Benefit only a single individual`], ans:1, exp:`Functionalism, associated with theorists like Durkheim and Parsons, views institutions as interdependent parts that each contribute to overall social stability and cohesion.` },
      { q:`Conflict theory's perspective on social institutions emphasizes that they often:`, ch:[`Equally benefit all social groups without exception`,`Can perpetuate and reinforce inequalities between social groups, particularly benefiting those in power`,`Have no relationship to power or inequality`,`Are entirely determined by biology`], ans:1, exp:`Conflict theorists argue that institutions can reflect and reinforce existing power structures, often benefiting dominant groups more than marginalized ones.` },
      { q:`The institution of "government" primarily functions to:`, ch:[`Provide entertainment for society`,`Create and enforce laws, maintain order, and provide services for the collective good`,`Replace the family`,`Have no impact on daily life`], ans:1, exp:`Government is the institution responsible for creating and enforcing laws, maintaining social order, and providing public services and collective decision-making structures.` },
      { q:`Which best describes the interconnected nature of social institutions?`, ch:[`Institutions operate in complete isolation from one another`,`Institutions like family, education, economy, and government influence and depend on one another`,`Only one institution matters in shaping society`,`Institutions never change over time`], ans:1, exp:`Social institutions are interdependent — for example, economic conditions can affect family stability, and educational policy can shape workforce readiness for the economy.` },
      { q:`According to symbolic interactionism, social institutions are best understood through:`, ch:[`Large-scale statistical trends only`,`The everyday meanings and interactions individuals create within and around institutions`,`Government mandates alone`,`Biological instincts`], ans:1, exp:`Symbolic interactionists focus on the micro-level, examining how individuals interpret and create meaning through everyday interactions within institutional settings.` },
      { q:`Which of the following represents institutional change over time?`, ch:[`Family structures remaining completely identical across all historical eras`,`The evolution of marriage laws and family structures across different historical periods and cultures`,`Educational institutions never adapting curricula`,`Religious institutions never changing practices`], ans:1, exp:`Social institutions evolve over time in response to cultural, legal, economic, and technological change, as seen in shifting definitions and legal structures of marriage and family.` },
      { q:`A society's healthcare system, as a social institution, exists primarily to:`, ch:[`Address only the government's economic goals`,`Organize the provision of medical care and address the health needs of the population`,`Replace family relationships`,`Determine which political party rules`], ans:1, exp:`Healthcare systems are organized institutions responsible for delivering medical services and addressing the health needs of a population.` },
      { q:`Which statement best reflects how institutions can produce unintended social consequences?`, ch:[`Institutions always produce exactly the outcomes they intend with no side effects`,`Policies designed for one purpose, such as housing, can create secondary effects on other institutions like education or health`,`Institutions have no influence beyond their stated purpose`,`Unintended consequences never occur in social systems`], ans:1, exp:`Because institutions are interconnected, a policy aimed at one area (e.g., housing policy) can have ripple effects on related institutions, such as school funding tied to local property taxes.` },
      { q:`Which of the following institutions is primarily responsible for the transmission of cultural values and knowledge across generations?`, ch:[`The economy`,`Education`,`The military`,`The stock market`], ans:1, exp:`Education is a key institution through which societies formally transmit knowledge, skills, and cultural values to younger generations.` },
      { q:`Which perspective would most likely argue that the education system can inadvertently reproduce existing social inequalities across generations?`, ch:[`Functionalism exclusively`,`Conflict theory`,`Behaviorism`,`Structuralism in linguistics`], ans:1, exp:`Conflict theorists emphasize how unequal access to resources within institutions like education can perpetuate existing class and social inequalities across generations.` },
    ]
  },
  {
    id:'ps130', cat:'Behavioral & Social Sciences', title:'Media & Society', diff:'Easy',
    qs:[
      { q:`The concept of "agenda-setting" in media studies refers to the idea that media:`, ch:[`Tell people exactly what to think about every issue`,`Influence what topics the public considers important, even without dictating specific opinions`,`Have no influence on public perception`,`Only report factual information without any selection`], ans:1, exp:`Agenda-setting theory holds that media coverage shapes which issues the public perceives as important, even if it does not directly dictate specific opinions on those issues.` },
      { q:`Media framing refers to:`, ch:[`The physical borders around a television screen`,`The way media present information, emphasizing certain aspects of a story that shape audience interpretation`,`A legal requirement for news accuracy`,`A type of censorship law`], ans:1, exp:`Framing involves selecting and emphasizing certain aspects of a story over others, which can shape how audiences interpret and understand the information presented.` },
      { q:`The "digital divide" refers to:`, ch:[`Political disagreements about internet regulation`,`The gap between individuals and communities with access to modern information technology and those without`,`A type of computer virus`,`A generational fashion trend`], ans:1, exp:`The digital divide describes unequal access to technology and the internet across different populations, often linked to income, geography, and infrastructure.` },
      { q:`Which of the following best describes "media literacy"?`, ch:[`The ability to operate any electronic device`,`The ability to access, analyze, evaluate, and create media in a variety of forms`,`Memorizing the names of news anchors`,`Avoiding all forms of media entirely`], ans:1, exp:`Media literacy involves critically engaging with media content — evaluating sources, recognizing bias, and understanding how media messages are constructed.` },
      { q:`Social media "echo chambers" occur when:`, ch:[`Users are exposed to a wide diversity of opposing viewpoints`,`Algorithms and personal choices expose users primarily to information that reinforces their existing beliefs`,`All social media platforms show identical content to every user`,`Media has no algorithmic curation at all`], ans:1, exp:`Echo chambers form when personalized algorithms and self-selected networks repeatedly expose users mainly to content that aligns with their existing views, limiting exposure to opposing perspectives.` },
      { q:`Which term describes the traditional role of journalism in monitoring government and society to inform the public, sometimes called the "fourth estate"?`, ch:[`Gatekeeping`,`The watchdog function of journalism`,`Propaganda`,`Cultivation theory`], ans:1, exp:`The watchdog function refers to journalism's role in scrutinizing those in power and informing the public, historically viewed as a check on government and institutions.` },
      { q:`Cultivation theory in media studies suggests that:`, ch:[`Media has no long-term effects on perceptions of reality`,`Long-term, heavy exposure to media content can shape viewers' perceptions of social reality, such as overestimating crime rates`,`Only children are affected by media content`,`Media consumption automatically improves critical thinking`], ans:1, exp:`Cultivation theory (Gerbner) proposes that prolonged, heavy media exposure gradually shapes viewers' beliefs about the real world, sometimes distorting perceptions such as the perceived prevalence of crime.` },
      { q:`"Gatekeeping" in media refers to the process by which:`, ch:[`Governments physically block internet access`,`Editors and media professionals decide which stories and information reach the public`,`All information is published without any selection`,`Audiences choose what journalists write`], ans:1, exp:`Gatekeeping describes the editorial decision-making process by which media professionals select, shape, and filter which stories are published or broadcast.` },
      { q:`The rise of social media has been associated with which notable shift in news consumption?`, ch:[`A complete elimination of traditional news organizations`,`A shift toward more decentralized information sources, including citizen journalism and viral sharing`,`Universal agreement on facts across all audiences`,`Reduced speed of information spread`], ans:1, exp:`Social media has enabled more decentralized news sharing, including citizen journalism and rapid, viral spread of information beyond traditional media gatekeepers.` },
      { q:`Which is a key concern researchers raise about the spread of misinformation on social media?`, ch:[`Misinformation spreads slower than verified information`,`Emotionally charged or sensational false content can spread rapidly, often faster than accurate corrections`,`Fact-checking organizations eliminate all misinformation instantly`,`Algorithms are designed to minimize engagement with any content`], ans:1, exp:`Research has found that sensational or emotionally charged misinformation can spread rapidly on social platforms, sometimes outpacing the reach of subsequent corrections.` },
      { q:`Media consolidation refers to:`, ch:[`The expansion of many independent, unrelated media outlets`,`A small number of large corporations owning an increasing share of media outlets`,`Government ownership of all newspapers`,`The complete disappearance of media companies`], ans:1, exp:`Media consolidation describes the trend of fewer, larger corporations controlling a greater share of media outlets, raising concerns about diversity of viewpoints.` },
      { q:`Parasocial relationships, a media phenomenon, describe:`, ch:[`Mutual friendships between two audience members`,`One-sided emotional connections audiences form with media figures, such as celebrities or influencers, who are unaware of them`,`Business partnerships between media companies`,`Government regulation of broadcasting`], ans:1, exp:`Parasocial relationships are one-sided bonds viewers or fans form with media personalities, who typically have no reciprocal awareness of the individual audience member.` },
      { q:`Which of the following best illustrates the concept of media's role in socialization?`, ch:[`Media has no influence on values, attitudes, or behavior`,`Children and adults can learn social norms, gender roles, and cultural values partly through exposure to television, film, and online content`,`Only schools can socialize individuals`,`Socialization ends after childhood`], ans:1, exp:`Media is considered an important agent of socialization, transmitting cultural norms, values, and role expectations to audiences across the lifespan.` },
    ]
  },
  {
    id:'ps131', cat:'Behavioral & Social Sciences', title:'Technology & Social Change', diff:'Medium',
    qs:[
      { q:`Sociologists use the term "technological determinism" to describe the view that:`, ch:[`Society entirely shapes technology with no reciprocal effect`,`Technology is a primary driving force behind social change and cultural values`,`Technology has no influence on society`,`Only economic factors drive social change`], ans:1, exp:`Technological determinism holds that technological innovations are a major driver of social and cultural change, sometimes contrasted with views emphasizing social shaping of technology.` },
      { q:`The term "digital divide" highlights inequality based on:`, ch:[`Age alone`,`Unequal access to and skills with information and communication technologies across different groups`,`Religious differences`,`Only rural versus urban housing styles`], ans:1, exp:`The digital divide describes disparities in access to, and effective use of, technology and the internet across different social groups.` },
      { q:`William Ogburn's concept of "cultural lag" refers to:`, ch:[`Technology and culture always changing at the same pace`,`The time gap between the introduction of new technology and society's adaptation of norms, laws, and institutions to it`,`A delay in scientific discovery`,`Culture changing faster than technology`], ans:1, exp:`Cultural lag describes the period during which nonmaterial culture — norms, laws, and institutions — struggles to catch up with rapid material/technological change.` },
      { q:`The Industrial Revolution's introduction of factory production most directly transformed which social institution?`, ch:[`Religion exclusively`,`Work and family life, as labor moved from home-based agriculture to centralized factories`,`The judiciary`,`Language`], ans:1, exp:`Industrialization shifted labor from agrarian, home-based production to centralized factories, reshaping family structure, daily routines, and the nature of work itself.` },
      { q:`Automation and artificial intelligence in the modern economy raise sociological concerns primarily about:`, ch:[`Guaranteed job security for all workers`,`Job displacement and the need for workforce retraining in affected industries`,`The elimination of all future technological change`,`Reduced global communication`], ans:1, exp:`A major sociological concern with automation and AI is the potential displacement of workers in affected industries and the resulting need for retraining and adaptation.` },
      { q:`The internet's effect on social movements has been most notably characterized by:`, ch:[`Making organizing and mobilizing large groups more difficult`,`Enabling rapid information sharing and coordination, lowering the cost of organizing collective action`,`Eliminating the need for any in-person action`,`Reducing global awareness of social issues`], ans:1, exp:`Digital communication tools have significantly lowered the cost and difficulty of coordinating and mobilizing collective action for social movements.` },
      { q:`Which concept describes how new technologies can create both intended benefits and unintended negative social consequences?`, ch:[`Technological determinism only`,`The dual nature (or "double-edged sword") of technology`,`Cultural lag exclusively`,`Media consolidation`], ans:1, exp:`Many technologies produce both intended benefits and unintended side effects, a pattern sociologists often describe as technology's double-edged nature.` },
      { q:`Social media platforms have been studied for their role in:`, ch:[`Eliminating political polarization entirely`,`Both connecting communities and, in some cases, contributing to polarization through selective exposure`,`Preventing any spread of information`,`Replacing all forms of face-to-face interaction with no drawbacks`], ans:1, exp:`Research indicates social media can both foster community connection and, through selective exposure and algorithmic curation, contribute to polarization in some contexts.` },
      { q:`The sociological concept of the "digital divide" has expanded in recent research to include a "second-level divide," referring to:`, ch:[`Differences in physical access to devices only`,`Differences in digital literacy and the ability to use technology effectively once access is available`,`A divide between two competing tech companies`,`A divide only relevant to developing countries`], ans:1, exp:`The "second-level digital divide" refers to disparities in skills and effective use of technology, beyond simple access to devices or internet connections.` },
      { q:`Which best explains why cultural lag can create social problems?`, ch:[`Laws and ethical norms may not keep pace with rapid technological change, such as data privacy issues outpacing regulation`,`Technology never changes faster than culture`,`Social norms always adapt instantly to new inventions`,`Cultural lag has no real-world consequences`], ans:0, exp:`When technology advances faster than the laws and norms meant to govern it, gaps can emerge — for example, privacy regulation often lags behind new data-collection technologies.` },
      { q:`Telecommuting and remote work, enabled by digital technology, have been associated with sociological shifts in:`, ch:[`The complete elimination of the workplace as a social institution`,`Work-life boundaries, urban and suburban living patterns, and traditional office-based social interaction`,`No changes to family or community life`,`A return to pre-industrial economies`], ans:1, exp:`Remote work technology has reshaped where and how people live and work, affecting boundaries between work and home life and patterns of urban and suburban settlement.` },
      { q:`The "network society," a term associated with sociologist Manuel Castells, describes:`, ch:[`A society structured around interconnected digital and information networks rather than solely physical or hierarchical structures`,`A society with no communication infrastructure`,`A pre-industrial agrarian society`,`A society entirely without institutions`], ans:0, exp:`Castells' concept of the network society describes modern societies increasingly organized around digital information networks that connect people, organizations, and economies globally.` },
      { q:`Which of the following best reflects a concern about surveillance technology in modern society?`, ch:[`Increased data collection by companies and governments raises questions about privacy and social control`,`Surveillance technology has no effect on personal privacy`,`Data collection is now technologically impossible`,`All surveillance concerns were resolved decades ago`], ans:0, exp:`The expansion of digital surveillance capabilities by both private companies and governments has raised ongoing sociological and ethical questions about privacy and social control.` },
    ]
  },
  {
    id:'ps132', cat:'Behavioral & Social Sciences', title:'Collective Behavior & Social Movements', diff:'Medium',
    qs:[
      { q:`In sociology, "collective behavior" refers to:`, ch:[`Highly organized, institutionalized behavior with clear rules`,`Relatively spontaneous, unstructured behavior of a group of people responding to a common situation, such as crowds, riots, or fads`,`Behavior exhibited only by isolated individuals`,`Government policy-making processes`], ans:1, exp:`Collective behavior refers to relatively spontaneous and less structured group behavior, in contrast to the organized, rule-based behavior typical of formal institutions.` },
      { q:`A social movement is best defined as:`, ch:[`A single spontaneous riot`,`An organized effort by a group of people to promote or resist social change`,`A government agency`,`A random crowd gathering with no shared purpose`], ans:1, exp:`Social movements are relatively organized, sustained collective efforts aimed at bringing about or resisting particular social or political changes.` },
      { q:`Resource mobilization theory explains the success of social movements primarily by emphasizing:`, ch:[`Spontaneous emotional outbursts alone`,`The ability of a movement to acquire and effectively use resources such as money, labor, and organizational skill`,`The complete absence of any leadership`,`Random chance`], ans:1, exp:`Resource mobilization theory argues that a movement's success depends significantly on its ability to organize and effectively deploy resources like funding, labor, and leadership.` },
      { q:`Which is an example of a "reform movement," as classified by sociologists?`, ch:[`A movement seeking to overthrow the entire existing social or political system`,`A movement seeking to change specific aspects of society, such as expanding voting rights, while working within the existing system`,`A brief, disorganized crowd panic`,`A purely religious ritual with no social goals`], ans:1, exp:`Reform movements seek targeted changes to specific policies or practices while generally working within existing political and social structures, unlike revolutionary movements that seek to replace the system entirely.` },
      { q:`Relative deprivation theory suggests that social movements often arise when people:`, ch:[`Are objectively at their lowest possible standard of living`,`Perceive a discrepancy between what they have and what they believe they are entitled to or deserve, compared to others`,`Have no comparison group whatsoever`,`Are entirely satisfied with their circumstances`], ans:1, exp:`Relative deprivation focuses on perceived, comparative disadvantage rather than absolute poverty — people may mobilize when they feel deprived relative to some reference group or expectation, even if their objective conditions have improved.` },
      { q:`"Frame alignment," a concept from social movement theory, refers to the process by which movement leaders:`, ch:[`Physically construct protest signs`,`Connect a movement's goals and ideology with the values and interests of potential participants to encourage recruitment`,`Avoid all public communication`,`Ignore public opinion entirely`], ans:1, exp:`Frame alignment describes how movement organizers connect their cause's framing with the existing beliefs and interests of potential supporters, aiding recruitment and mobilization.` },
      { q:`Which of the following best exemplifies "emergent norm theory" of collective behavior?`, ch:[`Crowds always follow pre-existing, fixed social rules identical to everyday life`,`New, situation-specific norms of behavior can emerge and spread within a crowd as people take cues from each other`,`Crowds are governed only by written laws`,`Individuals in a crowd never influence each other's behavior`], ans:1, exp:`Emergent norm theory proposes that crowds develop their own situational norms in real time, as participants observe and take behavioral cues from one another rather than following pre-set rules.` },
      { q:`A "fad" differs from a broader, lasting social movement in that a fad is typically:`, ch:[`Long-lasting and deeply tied to structural social change`,`A short-lived, widely followed trend or behavior with limited lasting social impact`,`Always politically motivated`,`Highly organized with formal leadership`], ans:1, exp:`Fads are brief, widely adopted trends that typically fade quickly and lack the sustained organization and structural goals of a true social movement.` },
      { q:`Which factor is commonly identified as necessary for a social movement to succeed over time?`, ch:[`Complete lack of organization`,`Effective leadership, sufficient resources, and a clear articulation of grievances and goals`,`Total absence of public attention`,`Avoiding any coalition-building`], ans:1, exp:`Sustained social movement success is typically linked to strong leadership, resource availability, clear goals, and the ability to build broader coalitions and public support.` },
      { q:`The term "moral panic" refers to:`, ch:[`A calm, rational public response to a minor issue`,`A widespread, intense public concern, often disproportionate to actual threat, about a perceived societal danger, frequently amplified by media`,`A type of formal social movement organization`,`A government policy tool`], ans:1, exp:`Moral panic describes an episode of exaggerated public fear or concern about a perceived threat to societal values, often fueled and amplified by media coverage.` },
      { q:`Counter-movements, in the study of social movements, are best described as:`, ch:[`Movements with no opposition whatsoever`,`Movements that arise in opposition to an existing social movement's goals`,`A synonym for the original movement`,`Movements that only exist in authoritarian states`], ans:1, exp:`Counter-movements emerge specifically in response to and opposition against an existing social movement's aims, often becoming active once the original movement gains momentum.` },
      { q:`Which best illustrates the "life cycle" model of social movements progressing through stages?`, ch:[`Emergence, coalescence, bureaucratization, and decline (or success)`,`A single, unchanging stage that never evolves`,`Movements that always begin and end within 24 hours`,`A model that applies only to violent movements`], ans:0, exp:`The life-cycle model describes social movements as typically progressing through stages of emergence, coalescence (organizing), bureaucratization (formalizing structure), and eventual decline or institutional success.` },
      { q:`Nonviolent civil disobedience, as a social movement tactic, is designed to:`, ch:[`Avoid any public attention to the cause`,`Draw attention to injustice and pressure for change while deliberately and openly refusing to comply with unjust laws`,`Comply completely and quietly with all existing laws`,`Eliminate the need for any organized effort`], ans:1, exp:`Civil disobedience involves openly and nonviolently refusing to comply with laws viewed as unjust, aiming to draw public attention and moral pressure toward changing those laws or policies.` },
    ]
  },
  {
    id:'ps133', cat:'Behavioral & Social Sciences', title:'Work & the Economy: A Sociological View', diff:'Medium',
    qs:[
      { q:`Sociologists distinguish the "primary," "secondary," and "tertiary" sectors of the economy based on:`, ch:[`Company size alone`,`Whether work involves extracting raw materials, manufacturing goods, or providing services`,`Employee salary levels`,`Geographic location only`], ans:1, exp:`These sectors are categorized by the type of economic activity: primary (raw material extraction, e.g., farming/mining), secondary (manufacturing), and tertiary (services).` },
      { q:`The shift from a manufacturing-based to a service- and information-based economy in many developed nations is often called:`, ch:[`Deindustrialization or the transition to a postindustrial economy`,`Reindustrialization`,`A return to agrarian economies`,`Total economic collapse`], ans:0, exp:`Many developed economies have shifted from manufacturing dominance toward service- and information-based industries, a transition often labeled deindustrialization or the move to a postindustrial economy.` },
      { q:`Alienation, a concept developed by Karl Marx in the context of industrial labor, refers to:`, ch:[`Workers feeling deeply connected to and fulfilled by their labor`,`Workers' sense of estrangement from the product of their labor, the labor process, and other workers under capitalist production`,`A government policy toward immigrants`,`A form of union organizing`], ans:1, exp:`Marx used "alienation" to describe how industrial workers can become estranged from the products they create, the process of labor itself, and their fellow workers under capitalist production systems.` },
      { q:`The "gig economy" refers to a labor market characterized by:`, ch:[`Long-term, guaranteed lifetime employment contracts`,`Short-term, flexible, freelance, or contract-based work arrangements rather than traditional full-time jobs`,`Exclusively unionized labor`,`Entirely unpaid volunteer work`], ans:1, exp:`The gig economy consists of short-term, flexible work arrangements, often facilitated by digital platforms, in contrast to traditional stable, full-time employment.` },
      { q:`Occupational segregation refers to the sociological pattern in which:`, ch:[`All occupations are equally distributed across demographic groups`,`Certain jobs and industries are disproportionately dominated by particular groups, such as by gender or race`,`Only government jobs show gender differences`,`Occupation has no relationship to social identity`], ans:1, exp:`Occupational segregation describes the uneven distribution of demographic groups across different jobs and industries, often studied in relation to gender and racial patterns in the labor market.` },
      { q:`The "glass ceiling" is a metaphor describing:`, ch:[`Physical office architecture`,`An invisible barrier that prevents qualified individuals, often women and minorities, from advancing to top leadership positions`,`A type of employee benefits package`,`A government regulation on hiring quotas`], ans:1, exp:`The glass ceiling metaphor refers to unseen but real barriers that limit the advancement of qualified individuals, often women and minorities, to senior leadership roles.` },
      { q:`Emile Durkheim's concept of the "division of labor" in modern societies refers to:`, ch:[`The complete absence of specialization`,`The specialization of work roles and interdependence among workers that characterizes complex, industrial societies`,`A system where every worker performs identical tasks`,`A term unrelated to economic structure`], ans:1, exp:`Durkheim examined how increasingly specialized work roles create interdependence among individuals in complex industrial societies, a shift from more simple, homogeneous social organization.` },
      { q:`Structural unemployment occurs when:`, ch:[`Workers are temporarily between jobs during a normal job search`,`There is a mismatch between workers' skills and the jobs available, often due to technological or economic change`,`The economy is at full employment`,`Seasonal industries lay off workers predictably each year`], ans:1, exp:`Structural unemployment arises from a mismatch between the skills workers have and what employers need, often due to industry shifts or automation, distinct from short-term frictional or seasonal unemployment.` },
      { q:`Sociological research on the "second shift" (Arlie Hochschild) describes:`, ch:[`Factory workers' overtime pay structure`,`The additional unpaid domestic and childcare labor, often performed disproportionately by women, after a paid workday`,`A government labor policy`,`A term for night-shift factory work only`], ans:1, exp:`Hochschild's "second shift" describes the additional unpaid household and caregiving labor that many working women perform after completing their paid jobs.` },
      { q:`Which best describes "credentialism" in the sociology of work?`, ch:[`Hiring based solely on informal recommendations`,`An increasing emphasis on formal educational degrees and certifications as job requirements, sometimes beyond what the job actually requires`,`The complete elimination of degree requirements`,`A focus purely on years of experience`], ans:1, exp:`Credentialism refers to the growing reliance on formal degrees or certifications as employment requirements, which some sociologists argue can exceed what is functionally necessary for a given job.` },
      { q:`Globalization has affected labor markets in developed economies partly by:`, ch:[`Eliminating all international trade`,`Enabling outsourcing of manufacturing and some service jobs to countries with lower labor costs`,`Guaranteeing job security in all industries`,`Having no measurable economic effect`], ans:1, exp:`Globalization has enabled companies to outsource certain manufacturing and service jobs to countries with lower labor costs, reshaping domestic labor markets in developed economies.` },
      { q:`Emile Durkheim argued that a breakdown of shared norms during periods of rapid economic change could produce:`, ch:[`Anomie — a state of normlessness associated with social instability`,`Perfect social cohesion`,`Increased division of labor with no social cost`,`A permanent decline in population`], ans:0, exp:`Durkheim's concept of anomie describes a state of normlessness that can arise during rapid social or economic change, when established norms no longer effectively guide behavior.` },
      { q:`Labor unions historically formed primarily to:`, ch:[`Represent management's interests exclusively`,`Collectively bargain for better wages, working conditions, and worker protections`,`Eliminate all forms of paid employment`,`Serve only government employees`], ans:1, exp:`Labor unions organize workers to collectively negotiate with employers for improved wages, hours, and working conditions, providing more bargaining power than individual workers typically have alone.` },
    ]
  },
  {
    id:'ps134', cat:'Behavioral & Social Sciences', title:'Education as a Social Institution', diff:'Easy',
    qs:[
      { q:`From a functionalist perspective, one key manifest function of education is to:`, ch:[`Reproduce social class inequality`,`Transmit knowledge and skills necessary for individuals to participate in society`,`Create social conflict`,`Serve no societal purpose`], ans:1, exp:`Functionalists view education's core, intended (manifest) function as equipping individuals with the knowledge and skills needed to participate productively in society.` },
      { q:`The "hidden curriculum" in schools refers to:`, ch:[`The official, published academic curriculum`,`Unspoken or implicit lessons about social norms, values, and expectations that students learn through the school experience`,`A secret set of textbooks`,`A government policy requiring standardized testing`], ans:1, exp:`The hidden curriculum consists of implicit lessons — about punctuality, obedience, competition, and social hierarchy — that students absorb through the everyday structure of schooling, beyond the official academic content.` },
      { q:`Conflict theorists argue that educational institutions can:`, ch:[`Provide identical opportunities and outcomes to all students regardless of background`,`Reproduce and reinforce existing social and economic inequalities across generations`,`Have no relationship whatsoever to social class`,`Eliminate all social stratification automatically`], ans:1, exp:`Conflict theorists emphasize how unequal resources and opportunities within educational systems can perpetuate existing social and economic inequalities rather than eliminate them.` },
      { q:`"Credential inflation" in education refers to:`, ch:[`Degrees becoming easier to earn over time`,`An increasing requirement for higher levels of formal education for jobs that previously required less, even without a change in job complexity`,`Declining numbers of college graduates`,`Reduced value placed on any formal education`], ans:1, exp:`Credential inflation describes the trend of employers requiring increasingly higher educational credentials for jobs, even when the actual skill demands of the job have not changed substantially.` },
      { q:`Tracking, in the sociology of education, refers to the practice of:`, ch:[`Recording student attendance`,`Grouping students into different educational paths, such as college-prep versus vocational, often based on perceived ability`,`Providing identical instruction to every student`,`A form of standardized testing scoring`], ans:1, exp:`Tracking sorts students into different curricular paths based on perceived academic ability or goals, a practice studied for its potential to reinforce social and economic disparities.` },
      { q:`Which of the following is an example of education serving a "latent function," an unintended or less obvious function?`, ch:[`Teaching literacy and math skills`,`Providing childcare and a venue for social networking or mate selection among students`,`Formal grading and diploma requirements`,`Standardized curriculum design`], ans:1, exp:`Latent functions are unintended byproducts of an institution — schools, beyond their explicit academic purpose, also provide childcare and serve as a social venue where students form relationships and networks.` },
      { q:`Research on the achievement gap in education has linked disparities in student outcomes partly to:`, ch:[`Purely genetic differences among racial groups`,`Socioeconomic factors such as school funding, access to resources, and family circumstances`,`A total absence of any environmental influence`,`Random chance with no identifiable patterns`], ans:1, exp:`Sociological research consistently links achievement gaps to structural and socioeconomic factors, including school funding disparities and access to educational resources, rather than to innate group differences.` },
      { q:`Horace Mann and other 19th-century reformers advocated for public education in the United States primarily to:`, ch:[`Restrict education to wealthy families only`,`Provide free, universal schooling to promote informed citizenship and social mobility`,`Eliminate all private schools immediately`,`Focus exclusively on religious instruction`], ans:1, exp:`Mann and other common-school reformers argued that free, universal public education would create a more informed citizenry and provide broader opportunities for social mobility.` },
      { q:`The sociological concept of "cultural capital" (Bourdieu) refers to:`, ch:[`Financial wealth exclusively`,`Non-financial social assets, such as education, language style, and cultural knowledge, that promote social mobility`,`A form of government subsidy for schools`,`A synonym for social capital with no distinction`], ans:1, exp:`Cultural capital refers to non-monetary assets — such as accumulated knowledge, tastes, and ways of speaking — that can facilitate social mobility and success within institutions like schools.` },
      { q:`School segregation by race was ruled unconstitutional in U.S. public schools by which landmark case?`, ch:[`Plessy v. Ferguson`,`Brown v. Board of Education (1954)`,`Marbury v. Madison`,`Miranda v. Arizona`], ans:1, exp:`Brown v. Board of Education (1954) overturned the "separate but equal" doctrine from Plessy v. Ferguson, ruling that racial segregation in public schools was unconstitutional.` },
      { q:`Standardized testing in education has been criticized by some sociologists for potentially:`, ch:[`Eliminating all forms of educational inequality`,`Reflecting and reinforcing disparities linked to socioeconomic status and access to test-preparation resources`,`Having no relationship to student outcomes`,`Applying identically across all school districts with no variation in resources`], ans:1, exp:`Critics argue that standardized test performance can reflect unequal access to test preparation, resources, and educational opportunities linked to socioeconomic status, rather than pure ability.` },
      { q:`Which best describes the "self-fulfilling prophecy" effect in education, such as the Pygmalion effect?`, ch:[`Teacher expectations of students have no impact on student performance`,`Teachers' expectations of student ability can influence student performance in ways that confirm those original expectations`,`Students' performance is entirely predetermined at birth`,`Only standardized tests can predict student outcomes`], ans:1, exp:`The Pygmalion effect describes how teacher expectations can subtly shape their behavior toward students, which in turn can influence student performance to align with those original expectations.` },
      { q:`Which statement reflects a functionalist view of education's role in "sorting" students?`, ch:[`Education has no role in preparing students for the labor market`,`Education helps sort and allocate individuals into appropriate societal roles based on ability and achievement`,`Schools should provide identical career outcomes for every student`,`Sorting students is unrelated to future occupational roles`], ans:1, exp:`Functionalists view education's sorting function as helping match individuals to appropriate societal and occupational roles based on demonstrated ability and achievement.` },
    ]
  },
  {
    id:'ps135', cat:'Behavioral & Social Sciences', title:'Religion as a Social Institution', diff:'Easy',
    qs:[
      { q:`Emile Durkheim argued that the core social function of religion is to:`, ch:[`Predict natural disasters`,`Create social cohesion and reinforce collective values and a sense of belonging among believers`,`Eliminate all social conflict permanently`,`Serve purely individual, private purposes with no social effect`], ans:1, exp:`Durkheim emphasized religion's role in binding communities together through shared rituals, symbols, and values, fostering social solidarity and a collective sense of belonging.` },
      { q:`Max Weber's study of the "Protestant Ethic" argued that certain religious values historically:`, ch:[`Had no relationship to economic behavior`,`Contributed to the rise of modern capitalism by emphasizing hard work, frugality, and worldly success as signs of religious virtue`,`Discouraged all forms of labor`,`Were identical across all world religions`], ans:1, exp:`Weber argued that certain Protestant values — emphasizing discipline, frugality, and hard work — helped foster attitudes conducive to the development of modern capitalism in parts of Europe.` },
      { q:`Karl Marx famously described religion as:`, ch:[`The primary driver of economic revolution`,`"The opium of the people" — a way of easing the pain of oppression while potentially discouraging challenges to social inequality`,`A purely neutral institution with no social function`,`The foundation of scientific reasoning`], ans:1, exp:`Marx viewed religion as providing comfort amid social suffering while potentially discouraging oppressed groups from challenging the economic and class structures causing that suffering.` },
      { q:`A denomination, as a type of religious organization, is generally characterized by:`, ch:[`Extreme hostility toward mainstream society`,`An established, mainstream religious organization that coexists with other denominations in relative tolerance`,`A single all-powerful world religious authority`,`Complete rejection of formal organization`], ans:1, exp:`Denominations are well-established religious organizations that typically coexist alongside other denominations in a society with relative mutual tolerance.` },
      { q:`Secularization refers to the sociological process by which:`, ch:[`Religious institutions gain increasing political power over time`,`Religion's influence on public life and institutions gradually declines in some societies`,`All religious belief is eliminated by law`,`Religious diversity is prohibited`], ans:1, exp:`Secularization describes a gradual decline in the social and institutional influence of religion in some societies, though the degree and pace of this process vary widely across the world.` },
      { q:`Civil religion refers to:`, ch:[`The official state-mandated religion of a theocracy`,`A set of shared, quasi-religious beliefs, symbols, and rituals tied to a nation, such as reverence for founding documents or national holidays`,`A specific denomination within Christianity`,`A term with no sociological meaning`], ans:1, exp:`Civil religion describes a set of national symbols, rituals, and shared beliefs that function in a quasi-religious way to unify citizens around collective national identity.` },
      { q:`Which best describes the difference between a "church" and a "sect" in sociological typology?`, ch:[`A church and sect are identical concepts`,`A church is typically a large, well-established religious organization integrated into society, while a sect is usually a smaller group that has broken away from a larger body, often in tension with society`,`A sect always has more members than a church`,`Churches never have any formal organization`], ans:1, exp:`In sociological typology, churches are large, established organizations well-integrated into mainstream society, whereas sects are smaller, breakaway groups often existing in higher tension with the surrounding culture.` },
      { q:`Religious pluralism refers to:`, ch:[`The existence of only one accepted religion within a society`,`A social environment in which multiple religious groups coexist within a society, often with mutual tolerance`,`The banning of religious practice`,`A single, unified world religion`], ans:1, exp:`Religious pluralism describes societies where multiple religious traditions coexist, often accompanied by legal protections and social norms supporting mutual tolerance.` },
      { q:`Which of the following is an example of a "manifest function" of religious institutions?`, ch:[`Unintentionally providing a marriage market for congregants`,`Providing formal rituals and doctrines for worship and moral guidance`,`Serving as a hidden venue for business networking`,`Accidentally reinforcing existing social class divisions`], ans:1, exp:`Manifest functions are the explicit, intended purposes of an institution — for religion, this includes formal worship practices and providing moral and doctrinal guidance to adherents.` },
      { q:`Fundamentalism, broadly defined in sociology of religion, refers to:`, ch:[`Religious movements emphasizing strict adherence to what adherents view as the fundamental or foundational teachings of their tradition, often in reaction to modern secular trends`,`A synonym for any mainstream denomination`,`A term describing only non-religious ideologies`,`The complete absence of religious doctrine`], ans:0, exp:`Fundamentalist movements emphasize strict adherence to foundational religious teachings, often emerging partly as a reaction against perceived secularizing or modernizing trends in society.` },
      { q:`A cult, or new religious movement, in sociological terms, is typically characterized by:`, ch:[`Long-established, mainstream traditions with millions of adherents`,`A relatively small, new religious group often organized around a charismatic leader, existing in high tension with the surrounding culture`,`Complete integration into mainstream religious denominations`,`Government sponsorship`], ans:1, exp:`New religious movements, sometimes labeled cults in sociological typology, are typically small, recently formed groups often centered on a charismatic leader and in significant tension with mainstream society.` },
      { q:`Which concept describes religion's role in providing answers to existential questions, such as the meaning of life, suffering, and death?`, ch:[`The economic function of religion`,`The meaning-making or existential function of religion`,`The political function of religion exclusively`,`A purely biological function`], ans:1, exp:`One widely recognized function of religion across cultures is providing frameworks for understanding existential questions, such as the meaning of suffering, death, and life's purpose.` },
      { q:`Interfaith dialogue and religious tolerance movements in modern pluralistic societies primarily aim to:`, ch:[`Eliminate all religious differences by force`,`Promote mutual understanding and peaceful coexistence among different religious groups`,`Establish a single global religion`,`Prohibit any public expression of faith`], ans:1, exp:`Interfaith dialogue initiatives generally seek to foster mutual understanding, respect, and peaceful coexistence among people of differing religious traditions.` },
    ]
  },
  {
    id:'ps136', cat:'Behavioral & Social Sciences', title:'Crime & the Criminal Justice System Basics', diff:'Medium',
    qs:[
      { q:`The criminal justice system is generally described as consisting of three main components:`, ch:[`Law enforcement (police), courts, and corrections`,`Legislature, executive, and judiciary only`,`Family, education, and religion`,`Media, economy, and government`], ans:0, exp:`The criminal justice system is typically described as three interconnected components: law enforcement (investigating and arresting), courts (adjudicating guilt or innocence), and corrections (managing sentences).` },
      { q:`Strain theory (Robert Merton) explains crime as arising from:`, ch:[`Purely biological predispositions`,`A disconnect between culturally valued goals, such as wealth, and the legitimate means available to achieve them`,`Random individual choice with no social pattern`,`Religious institutions failing to provide guidance`], ans:1, exp:`Merton's strain theory argues that when people lack legitimate means to achieve culturally approved goals (like financial success), some may turn to illegitimate means, including crime.` },
      { q:`Differential association theory (Edwin Sutherland) proposes that criminal behavior is learned through:`, ch:[`Genetic inheritance alone`,`Interaction and association with others who hold favorable attitudes toward criminal behavior`,`A single traumatic event`,`Media exposure exclusively`], ans:1, exp:`Sutherland's theory holds that individuals learn criminal behavior, including techniques and attitudes favorable to crime, through interactions with others, especially close associates.` },
      { q:`Labeling theory in criminology suggests that:`, ch:[`Being labeled "deviant" or "criminal" has no effect on future behavior`,`Society's reaction to and labeling of an individual as deviant can reinforce and perpetuate future deviant behavior`,`All crime is defined identically across every culture`,`Formal labels always reduce criminal behavior`], ans:1, exp:`Labeling theory argues that once someone is officially labeled as deviant or criminal, that label can shape their self-identity and social treatment in ways that reinforce continued deviant behavior.` },
      { q:`The distinction between a "felony" and a "misdemeanor" is primarily based on:`, ch:[`The defendant's age`,`The severity of the crime and the length of potential punishment, with felonies being more serious`,`Whether the crime was committed in public`,`The number of witnesses present`], ans:1, exp:`Felonies are more serious crimes carrying longer potential sentences, typically over a year, while misdemeanors are less severe offenses with shorter maximum sentences.` },
      { q:`Recidivism refers to:`, ch:[`A first-time criminal offense`,`The tendency of a previously convicted individual to reoffend`,`A type of legal defense`,`A court's initial sentencing decision`], ans:1, exp:`Recidivism describes the rate at which individuals who have been previously convicted go on to commit further offenses after release.` },
      { q:`The presumption of innocence, a foundational principle of the U.S. criminal justice system, means that:`, ch:[`Defendants must prove their own innocence`,`The prosecution bears the burden of proving guilt beyond a reasonable doubt`,`Juries assume guilt until proven otherwise`,`Judges alone determine guilt without a trial`], ans:1, exp:`Under the presumption of innocence, the burden of proof rests on the prosecution to establish guilt beyond a reasonable doubt, rather than requiring the defendant to prove their innocence.` },
      { q:`Which of the following best describes the difference between retributive and rehabilitative approaches to punishment?`, ch:[`Retributive justice focuses on punishing offenders proportionate to their crime, while rehabilitative justice focuses on reforming offenders to reduce future offending`,`Both approaches are identical in practice`,`Rehabilitative justice focuses only on victim compensation`,`Retributive justice focuses solely on offender therapy`], ans:0, exp:`Retributive justice emphasizes proportionate punishment for wrongdoing, while rehabilitative justice emphasizes reforming offenders through treatment and support to reduce future reoffending.` },
      { q:`Plea bargaining in the criminal justice system refers to:`, ch:[`A jury's final verdict`,`An agreement in which a defendant pleads guilty to a lesser charge or receives a reduced sentence in exchange for avoiding a full trial`,`A type of appeal process`,`A form of jury nullification`], ans:1, exp:`Plea bargaining involves negotiations in which a defendant agrees to plead guilty, often to a lesser charge, in exchange for a reduced sentence or other concessions, avoiding the need for a full trial.` },
      { q:`Racial disparities in incarceration rates in the U.S. have been studied by sociologists in relation to factors such as:`, ch:[`Differences in policing patterns, sentencing practices, and socioeconomic conditions across communities`,`Purely random chance with no identifiable social patterns`,`Only differences in individual moral character`,`A single uniform national policy with no regional variation`], ans:0, exp:`Researchers have linked racial disparities in incarceration to a range of structural factors, including differences in policing practices, sentencing outcomes, and broader socioeconomic conditions.` },
      { q:`Restorative justice is an approach to criminal justice that emphasizes:`, ch:[`Solely punitive incarceration`,`Repairing harm through dialogue and accountability between offenders, victims, and the community`,`Eliminating all forms of punishment`,`Reducing court involvement to zero`], ans:1, exp:`Restorative justice focuses on repairing the harm caused by crime through structured dialogue and accountability among offenders, victims, and the broader community, as an alternative or complement to purely punitive approaches.` },
      { q:`White-collar crime, a term coined by Edwin Sutherland, refers to:`, ch:[`Violent street crime exclusively`,`Financially motivated, nonviolent crimes committed typically by business or government professionals, such as fraud or embezzlement`,`Only crimes committed by unemployed individuals`,`A category of crime that no longer exists`], ans:1, exp:`White-collar crime describes financially motivated, typically nonviolent offenses committed by individuals in professional or business settings, such as fraud, embezzlement, and insider trading.` },
      { q:`The exclusionary rule in U.S. law generally holds that:`, ch:[`Evidence obtained through illegal searches may still always be used in court`,`Evidence obtained in violation of a defendant's constitutional rights, such as an unlawful search, is generally inadmissible in court`,`Only confessions can be excluded from trial`,`All evidence must be excluded regardless of how it was obtained`], ans:1, exp:`The exclusionary rule generally prevents evidence gathered in violation of a defendant's constitutional protections, such as through an unlawful search, from being used against them at trial.` },
    ]
  },
  {
    id:'ps137', cat:'Behavioral & Social Sciences', title:'Health & Illness as a Social Phenomenon', diff:'Medium',
    qs:[
      { q:`Talcott Parsons' concept of the "sick role" describes:`, ch:[`A set of social expectations and exemptions granted to individuals recognized as legitimately ill, such as being excused from normal duties while seeking treatment`,`A legal designation applied only to chronic illness`,`A term describing malingering`,`A medical diagnosis category`], ans:0, exp:`Parsons' sick role concept describes the social expectations attached to being recognized as legitimately ill, including temporary exemption from normal responsibilities, in exchange for seeking appropriate treatment.` },
      { q:`According to the sick role concept, in exchange for exemption from normal responsibilities, a sick individual is expected to:`, ch:[`Avoid seeking any medical treatment`,`Want to get well and cooperate with medical treatment`,`Continue all normal social obligations unchanged`,`Permanently withdraw from society`], ans:1, exp:`The sick role involves a reciprocal obligation: in exchange for exemption from normal duties, the person is expected to genuinely want to recover and to cooperate with appropriate medical care.` },
      { q:`"Medicalization" refers to the sociological process by which:`, ch:[`Medical conditions are removed from social discussion entirely`,`Previously non-medical conditions or behaviors come to be defined and treated as medical problems`,`All social problems are solved through medicine`,`Illness is defined purely by legal statute`], ans:1, exp:`Medicalization describes how behaviors or conditions once viewed in non-medical (e.g., moral, social) terms come to be defined and addressed as medical issues requiring diagnosis and treatment.` },
      { q:`The social construction of illness suggests that:`, ch:[`Illness is purely a biological phenomenon with no social dimension`,`Cultural and social context shapes how a condition is understood, labeled, and experienced, in addition to biological factors`,`Only mental illnesses have social components`,`Physical diseases have no relationship to social meaning`], ans:1, exp:`This perspective emphasizes that while illness has biological reality, cultural and social context also strongly shapes how conditions are labeled, perceived, stigmatized, and experienced.` },
      { q:`Which best illustrates stigma associated with illness, as studied in medical sociology?`, ch:[`Universal sympathy shown equally to all illnesses`,`Certain conditions, such as some mental illnesses or infectious diseases, carry social discrediting or negative labeling beyond their medical symptoms`,`All diseases carry identical levels of public perception`,`Stigma has been eliminated in modern healthcare systems`], ans:1, exp:`Medical sociologists have documented how certain conditions carry additional social stigma and discrediting labels beyond their medical symptoms, which can affect treatment-seeking and social relationships.` },
      { q:`Social epidemiology studies the:`, ch:[`Purely genetic causes of individual diseases`,`Distribution and social determinants of health and disease patterns across populations`,`Legal regulation of hospitals only`,`Marketing practices of pharmaceutical companies`], ans:1, exp:`Social epidemiology examines how social factors — such as income, education, and social environment — are distributed and how they relate to patterns of health and disease across populations.` },
      { q:`Which of the following best describes "illness behavior" as a sociological concept?`, ch:[`The biological symptoms of a disease itself`,`How individuals perceive, evaluate, and act upon symptoms, including whether and when they seek care`,`The dosage of medication prescribed`,`A hospital's billing procedures`], ans:1, exp:`Illness behavior refers to the process by which individuals notice, interpret, and respond to symptoms, including decisions about whether, when, and how to seek professional care.` },
      { q:`Chronic illness has been studied sociologically for its impact on:`, ch:[`Only the biological body, with no effect on identity or relationships`,`Patients' identity, daily routines, and social relationships, often requiring significant biographical and lifestyle adjustment`,`Government tax policy exclusively`,`The stock market`], ans:1, exp:`Sociologists studying chronic illness examine how long-term conditions can require patients to substantially adjust their identity, daily routines, and relationships, a process sometimes called "biographical disruption."` },
      { q:`The concept of "health disparities" in medical sociology refers to:`, ch:[`Identical health outcomes across all social groups`,`Differences in health outcomes and access to care that are closely linked to social factors such as income, race, and geography`,`Differences purely due to individual genetics`,`A term used only in veterinary medicine`], ans:1, exp:`Health disparities describe measurable gaps in health outcomes and healthcare access that are systematically linked to social factors like income, race, and geographic location.` },
      { q:`Which of these is an example of medicalization discussed in sociological literature?`, ch:[`Treating a broken bone in an emergency room`,`The shift toward diagnosing and treating conditions like childbirth, shyness, or unwanted behavior patterns as medical issues requiring treatment`,`A hospital's parking policy`,`A doctor's personal political opinion`], ans:1, exp:`Sociologists have documented medicalization in areas such as childbirth, shyness (social anxiety), and other behaviors that were previously understood in non-medical terms but have increasingly been framed as conditions requiring medical diagnosis and treatment.` },
      { q:`Critics of medicalization argue that it can:`, ch:[`Only ever benefit patients with no downsides`,`Sometimes overextend medical authority into normal human variation, potentially pathologizing typical behavior`,`Eliminate all social stigma associated with illness`,`Have no relationship to pharmaceutical industry interests`], ans:1, exp:`Critics contend that medicalization can sometimes extend medical labels and treatment to ordinary variations in human experience, potentially pathologizing behaviors that fall within a typical range.` },
      { q:`Which factor is commonly cited by medical sociologists as shaping whether someone seeks professional healthcare for symptoms?`, ch:[`Symptom severity alone, with no other factors relevant`,`A combination of symptom severity, cultural beliefs about illness, cost, and access to care`,`A person's height`,`Purely random chance`], ans:1, exp:`Decisions about seeking healthcare are shaped by multiple interacting factors, including how severe symptoms seem, cultural beliefs about illness and treatment, financial cost, and access to services.` },
      { q:`A sociological perspective on disability emphasizes that limitations experienced by people with disabilities are partly shaped by:`, ch:[`Biology alone, with society playing no role`,`Social and environmental barriers, such as inaccessible buildings and discrimination, not solely by an individual's physical or mental condition`,`Personal choice to be disabled`,`A condition that cannot be studied sociologically`], ans:1, exp:`The social model of disability emphasizes that many limitations experienced by people with disabilities stem from societal and environmental barriers, such as inaccessible infrastructure or discriminatory attitudes, not solely from the individual's own physical or mental condition.` },
    ]
  },
  {
    id:'ps138', cat:'Behavioral & Social Sciences', title:'The Cold War & 1950s America', diff:'Medium',
    qs:[
      { q:`The Cold War was primarily characterized by:`, ch:[`Direct, large-scale military conflict between the United States and the Soviet Union`,`An extended period of geopolitical tension, ideological rivalry, and proxy conflicts between the U.S.-led and Soviet-led blocs without direct large-scale war between the two superpowers`,`A period of complete cooperation between the U.S. and USSR`,`A war fought exclusively in Europe`], ans:1, exp:`The Cold War was defined by prolonged ideological and geopolitical rivalry, proxy wars, and an arms race between the U.S. and USSR, without direct large-scale military conflict between the two superpowers themselves.` },
      { q:`The policy of "containment," articulated by George Kennan, called for the United States to:`, ch:[`Actively invade and overthrow communist governments worldwide`,`Prevent the further spread of communism through diplomatic, economic, and military means without direct war with the Soviet Union`,`Withdraw from all international affairs`,`Fully adopt socialist economic policies`], ans:1, exp:`Containment aimed to limit the spread of Soviet-backed communism through diplomacy, economic aid, and military support, generally without seeking direct war against the Soviet Union.` },
      { q:`The Marshall Plan (1948) was a U.S. program designed to:`, ch:[`Provide economic aid to help rebuild Western European economies after World War II, partly to prevent the spread of communism`,`Fund a military invasion of Eastern Europe`,`Establish colonies in Africa`,`Provide aid exclusively to the Soviet Union`], ans:0, exp:`The Marshall Plan provided substantial U.S. economic aid to help rebuild war-torn Western European economies, partly with the goal of stabilizing these nations against the appeal of communism.` },
      { q:`The Korean War (1950-1953) is best understood as:`, ch:[`A war between the United States and Japan`,`A Cold War-era proxy conflict in which U.S.-led UN forces supported South Korea against North Korea, which was backed by China and the USSR`,`A purely civil dispute with no international involvement`,`A conflict that ended in a formal peace treaty and full reunification`], ans:1, exp:`The Korean War was a major Cold War proxy conflict, with UN forces led largely by the U.S. supporting South Korea against North Korean forces backed by China and the Soviet Union, ending in an armistice rather than full reunification.` },
      { q:`Senator Joseph McCarthy is most associated with:`, ch:[`Leading anti-communist investigations and hearings in the early 1950s that included often unsubstantiated accusations of communist infiltration`,`Negotiating the end of the Korean War`,`Founding the Marshall Plan`,`Serving as U.S. president during the 1950s`], ans:0, exp:`McCarthy led prominent anti-communist investigations in the early 1950s, often making sweeping and largely unsubstantiated accusations of communist infiltration in government and other institutions.` },
      { q:`The term "Red Scare" (in its 1950s form) refers to:`, ch:[`Widespread public and government fear of communist subversion within the United States`,`A popular fashion trend`,`A U.S. military campaign in Korea`,`An economic recession`], ans:0, exp:`The second Red Scare refers to the intense fear of communist infiltration and subversion within the United States during the late 1940s and 1950s, fueling investigations and blacklists.` },
      { q:`The 1950s in the United States are commonly associated with which economic and social trend?`, ch:[`Widespread economic depression`,`Post-WWII economic prosperity, suburban growth, and the expansion of a consumer culture`,`A collapse of the manufacturing sector`,`Mass emigration from the United States`], ans:1, exp:`The postwar 1950s saw significant U.S. economic growth, expansion of suburbs, and a rise in consumer culture, aided by factors like the GI Bill and highway construction.` },
      { q:`The policy of "mutually assured destruction" (MAD) referred to:`, ch:[`A shared belief that any large-scale nuclear attack would result in the total destruction of both the attacker and defender, deterring either side from initiating nuclear war`,`A treaty banning all nuclear weapons`,`A plan to jointly develop nuclear weapons between rival nations`,`A term for conventional warfare strategy only`], ans:0, exp:`MAD described the deterrence logic that a full-scale nuclear exchange would devastate both sides, theoretically discouraging either superpower from launching a first strike.` },
      { q:`The 1957 launch of Sputnik by the Soviet Union led the United States to:`, ch:[`Abandon its space program entirely`,`Accelerate investment in science education and space technology, eventually leading to the creation of NASA`,`Form a full military alliance with the USSR`,`End the Cold War immediately`], ans:1, exp:`Sputnik's launch shocked American policymakers and spurred significant new investment in science, technology education, and space exploration, culminating in NASA's creation in 1958.` },
      { q:`The Cuban Missile Crisis (1962) was triggered by:`, ch:[`The discovery of Soviet nuclear missile installations in Cuba, close to the United States`,`A direct Soviet invasion of the United States`,`The overthrow of the U.S. government`,`A trade dispute between the U.S. and Cuba`], ans:0, exp:`The crisis began when U.S. reconnaissance discovered Soviet nuclear missile installations being built in Cuba, prompting a tense standoff that brought the two superpowers close to direct conflict.` },
      { q:`NATO (North Atlantic Treaty Organization), formed in 1949, was created primarily as:`, ch:[`An economic trade agreement`,`A mutual-defense military alliance among Western nations aimed at collective security against Soviet expansion`,`A cultural exchange program`,`A United Nations subcommittee`], ans:1, exp:`NATO was established as a collective defense alliance among Western nations, designed to provide mutual military security against the perceived threat of Soviet expansion.` },
      { q:`The Warsaw Pact (1955) served as:`, ch:[`The Soviet-led military alliance counterpart to NATO, comprising the USSR and its Eastern European allies`,`A Western European trade bloc`,`A UN peacekeeping force`,`An agreement to disarm all Cold War nations`], ans:0, exp:`The Warsaw Pact was the Soviet-led mutual defense alliance formed in response to NATO, uniting the USSR with its Eastern European satellite states.` },
      { q:`Suburbanization in 1950s America was significantly fueled by:`, ch:[`A decline in automobile ownership`,`Federal highway construction, GI Bill housing benefits, and mass-produced housing developments`,`A ban on home construction`,`A mass return to urban apartment living`], ans:1, exp:`Postwar suburban growth was driven by factors including the interstate highway system, GI Bill mortgage benefits for veterans, and the rise of mass-produced housing developments like Levittown.` },
    ]
  },
  {
    id:'ps139', cat:'Behavioral & Social Sciences', title:'The Vietnam War Era', diff:'Medium',
    qs:[
      { q:`U.S. involvement in Vietnam grew out of the broader Cold War policy of:`, ch:[`Isolationism`,`Containment of communism, particularly concern over the "domino theory" that communism would spread to neighboring countries`,`Direct alliance with communist movements`,`Total withdrawal from Southeast Asia`], ans:1, exp:`U.S. policymakers viewed involvement in Vietnam through the lens of Cold War containment, fearing that a communist victory could trigger a "domino effect" of communism spreading through Southeast Asia.` },
      { q:`The Gulf of Tonkin Resolution (1964) is significant because it:`, ch:[`Ended U.S. involvement in Vietnam`,`Granted the U.S. president broad authority to escalate U.S. military involvement in Vietnam without a formal declaration of war`,`Established the United Nations`,`Was a peace treaty ending the war`], ans:1, exp:`The resolution, passed by Congress after reported naval incidents, gave the president expanded authority to escalate U.S. military action in Vietnam without a formal congressional declaration of war.` },
      { q:`The Tet Offensive (1968) is considered a turning point in the war primarily because it:`, ch:[`Resulted in an immediate, decisive U.S. military defeat leading to withdrawal`,`Shocked American public opinion and undermined confidence in official claims that the war was close to being won, despite being largely a military setback for North Vietnamese and Viet Cong forces`,`Marked the first U.S. troops entering Vietnam`,`Ended all combat operations`], ans:1, exp:`Although a military setback for communist forces, the surprise scale of the Tet Offensive shocked American public opinion and undercut official assurances that the war was nearly won, shifting domestic political momentum.` },
      { q:`The draft (Selective Service conscription) during the Vietnam War contributed to:`, ch:[`Widespread public support for the war with no dissent`,`Significant social unrest and antiwar protests, particularly among college-age youth facing potential conscription`,`The immediate end of U.S. involvement in 1965`,`A complete absence of controversy`], ans:1, exp:`Mandatory conscription intensified antiwar sentiment, especially among young people directly facing the possibility of being drafted, fueling significant protest movements.` },
      { q:`The "Vietnamization" policy under President Nixon aimed to:`, ch:[`Increase the number of U.S. combat troops in Vietnam significantly`,`Gradually shift combat responsibility to South Vietnamese forces while reducing U.S. troop levels`,`End all U.S. financial support for South Vietnam immediately`,`Formally annex Vietnam as a U.S. territory`], ans:1, exp:`Vietnamization sought to gradually transfer combat responsibilities to South Vietnamese forces while reducing the number of U.S. troops deployed in the conflict.` },
      { q:`The Paris Peace Accords (1973) resulted in:`, ch:[`A permanent, lasting division of Vietnam into two separate countries`,`A ceasefire and withdrawal of U.S. combat troops, though fighting between North and South Vietnam continued until 1975`,`Immediate reunification under a democratic government`,`A U.S. military victory over North Vietnam`], ans:1, exp:`The accords established a ceasefire and led to U.S. troop withdrawal, but fighting between North and South Vietnamese forces resumed and continued until the fall of Saigon in 1975.` },
      { q:`The fall of Saigon in 1975 marked:`, ch:[`The reunification of Vietnam under Communist control after North Vietnamese forces took the South Vietnamese capital`,`A U.S. military victory`,`The founding of South Vietnam as an independent nation`,`The start of U.S. involvement in the war`], ans:0, exp:`The fall of Saigon in 1975 marked the end of the war, with North Vietnamese forces capturing the South Vietnamese capital and leading to national reunification under Communist rule.` },
      { q:`Antiwar protests in the U.S. during the Vietnam era, such as those at Kent State University in 1970, reflected:`, ch:[`Universal public approval of the war`,`Deep social and political divisions over U.S. military involvement in Vietnam`,`A movement entirely unrelated to the war`,`Only international, not domestic, opposition`], ans:1, exp:`Events like the Kent State shootings highlighted the deep and often violent domestic divisions surrounding U.S. involvement in Vietnam during this period.` },
      { q:`The "Pentagon Papers," leaked in 1971, revealed:`, ch:[`That the war was progressing exactly as publicly reported`,`Internal government assessments showing discrepancies between public statements and private assessments about the war's prospects`,`A secret peace treaty`,`Plans for a nuclear strike`], ans:1, exp:`The Pentagon Papers exposed internal government analyses showing significant gaps between official public optimism about the war and private, more pessimistic assessments.` },
      { q:`The Vietnam War is often cited as contributing to which broader shift in American public attitudes?`, ch:[`Increased public trust in government institutions`,`Growing skepticism toward government claims and increased scrutiny of military engagements abroad`,`A decline in media coverage of foreign policy`,`Universal consensus supporting future foreign interventions`], ans:1, exp:`The war and revelations like the Pentagon Papers contributed to increased public skepticism toward official government statements and greater scrutiny of subsequent U.S. military interventions abroad.` },
      { q:`Agent Orange, used by U.S. forces during the war, was:`, ch:[`A type of currency used in South Vietnam`,`A herbicide used to defoliate forests and destroy crops, later linked to serious health effects among exposed veterans and Vietnamese civilians`,`A diplomatic code name for peace talks`,`A type of military uniform`], ans:1, exp:`Agent Orange was a chemical herbicide used to clear vegetation and destroy crops, later associated with significant long-term health effects among exposed U.S. veterans and Vietnamese civilians.` },
      { q:`The domino theory, influential in U.S. Cold War policy toward Vietnam, held that:`, ch:[`Communist takeover of one country would have no effect on neighboring nations`,`If one country in a region fell to communism, neighboring countries would likely follow in a chain reaction`,`Vietnam had no strategic importance to the U.S.`,`Communism could only spread through direct military invasion`], ans:1, exp:`The domino theory proposed that a communist victory in one country could trigger a chain reaction of communist takeovers in neighboring nations, shaping U.S. policy justification for intervention.` },
      { q:`Veterans returning from the Vietnam War often faced:`, ch:[`Uniformly celebratory public receptions with no controversy`,`Mixed and sometimes hostile public reactions, along with difficulties reintegrating and receiving support for war-related trauma`,`Immediate, universal government support with no gaps in care`,`No lasting psychological or social effects`], ans:1, exp:`Many Vietnam veterans encountered mixed or hostile public reactions upon return and faced significant challenges in reintegration and accessing adequate support for war-related psychological trauma.` },
    ]
  },
  {
    id:'ps140', cat:'Behavioral & Social Sciences', title:'America in the 1980s and 1990s', diff:'Easy',
    qs:[
      { q:`"Reaganomics," associated with President Ronald Reagan in the 1980s, emphasized:`, ch:[`Increased government spending on social welfare programs`,`Tax cuts, deregulation, and reduced government spending on some domestic programs, based on supply-side economic theory`,`Nationalization of major industries`,`A return to a fully agrarian economy`], ans:1, exp:`Reaganomics emphasized supply-side economic principles, including significant tax cuts, deregulation, and reduced spending on certain domestic programs, aiming to stimulate economic growth.` },
      { q:`The end of the Cold War in the early 1990s was marked most notably by:`, ch:[`The start of the Korean War`,`The fall of the Berlin Wall (1989) and the subsequent dissolution of the Soviet Union (1991)`,`The beginning of World War II`,`The founding of NATO`], ans:1, exp:`The fall of the Berlin Wall in 1989 and the formal dissolution of the Soviet Union in 1991 are widely regarded as marking the end of the Cold War era.` },
      { q:`The Gulf War (1990-1991) was fought primarily in response to:`, ch:[`Iraq's invasion of Kuwait`,`A direct attack on the United States mainland`,`A civil war within Saudi Arabia`,`A trade dispute between the U.S. and Iraq`], ans:0, exp:`A U.S.-led international coalition launched military action after Iraq invaded and occupied its neighbor Kuwait in 1990.` },
      { q:`The AIDS epidemic became a major public health and social issue in the United States beginning in:`, ch:[`The 1930s`,`The early 1980s`,`The 1960s`,`The 2000s`], ans:1, exp:`AIDS was first identified as an emerging public health crisis in the United States in the early 1980s, becoming a significant social and political issue throughout that decade.` },
      { q:`The personal computer and early internet technologies saw significant growth and commercialization primarily during:`, ch:[`The 1920s`,`The 1980s and 1990s`,`The 1950s`,`The 1800s`], ans:1, exp:`Personal computers became widely commercially available in the 1980s, and the internet expanded rapidly into mainstream use during the 1990s.` },
      { q:`NAFTA (North American Free Trade Agreement), signed in the early 1990s, aimed to:`, ch:[`End all trade between the U.S., Canada, and Mexico`,`Reduce trade barriers and promote free trade among the United States, Canada, and Mexico`,`Establish a shared currency across North America`,`Restrict immigration exclusively`], ans:1, exp:`NAFTA aimed to reduce tariffs and other trade barriers to promote greater economic integration and free trade among the United States, Canada, and Mexico.` },
      { q:`The Iran-Contra affair, a major political scandal of the 1980s, involved:`, ch:[`A public and fully authorized arms sale to Iran`,`Secret U.S. arms sales to Iran and the diversion of profits to fund Contra rebels in Nicaragua, in violation of congressional restrictions`,`A direct U.S. military invasion of Iran`,`A trade agreement with the Soviet Union`], ans:1, exp:`The Iran-Contra affair involved covert arms sales to Iran, with proceeds secretly diverted to fund Contra rebels in Nicaragua, in violation of congressional restrictions on such funding.` },
      { q:`The 1980s in the United States saw a notable rise in which cultural and media phenomenon?`, ch:[`The complete disappearance of television`,`Cable television and the growth of channels like MTV and CNN`,`A return to silent films`,`The banning of home video technology`], ans:1, exp:`The 1980s saw significant expansion of cable television, including the launch and growth of channels such as MTV and CNN, reshaping American media consumption.` },
      { q:`The Los Angeles riots of 1992 were sparked by:`, ch:[`A natural disaster`,`The acquittal of police officers filmed beating Rodney King, an incident that intensified national debate over policing and racial justice`,`A stock market crash`,`A presidential election dispute`], ans:1, exp:`The 1992 riots followed the acquittal of police officers involved in the videotaped beating of Rodney King, intensifying national debate over policing practices and racial justice.` },
      { q:`The Oklahoma City bombing (1995) was an act of domestic terrorism that:`, ch:[`Was carried out by a foreign government`,`Killed 168 people and heightened national attention to domestic extremism`,`Occurred in New York City`,`Targeted an airport`], ans:1, exp:`The 1995 bombing of the Alfred P. Murrah Federal Building in Oklahoma City killed 168 people and was carried out by domestic extremists, heightening national attention to domestic terrorism.` },
      { q:`The 1990s U.S. economy is often associated with:`, ch:[`A prolonged recession with high unemployment throughout the decade`,`Significant economic growth driven partly by the technology and "dot-com" boom`,`A return to a primarily agricultural economy`,`The elimination of the stock market`], ans:1, exp:`The 1990s saw substantial U.S. economic expansion, driven in part by growth in technology industries and the rise of internet-based ("dot-com") companies.` },
      { q:`The Family and Medical Leave Act (1993) was significant because it:`, ch:[`Eliminated all workplace protections`,`Guaranteed eligible employees unpaid, job-protected leave for certain family and medical reasons`,`Mandated paid leave for all workers nationwide`,`Applied only to federal government employees`], ans:1, exp:`The Family and Medical Leave Act guaranteed eligible employees the right to take unpaid, job-protected leave for specified family and medical situations.` },
      { q:`The end of the Cold War prompted a major shift in U.S. foreign policy focus during the 1990s toward:`, ch:[`Escalating tensions with a still-unified Soviet Union`,`Addressing regional conflicts, humanitarian interventions, and questions about America's post-Cold War global role`,`Total military withdrawal from all international engagement`,`A renewed nuclear arms race with Russia`], ans:1, exp:`With the Cold War's end, U.S. foreign policy in the 1990s increasingly focused on regional conflicts, humanitarian interventions, and debates about America's evolving role as the primary global power.` },
    ]
  },
  {
    id:'ps141', cat:'Behavioral & Social Sciences', title:'American Immigration History', diff:'Medium',
    qs:[
      { q:`The Chinese Exclusion Act of 1882 was significant because it:`, ch:[`Encouraged unlimited Chinese immigration to the U.S.`,`Was the first major U.S. law to restrict immigration based explicitly on nationality, banning most Chinese laborers`,`Granted automatic citizenship to Chinese immigrants`,`Applied equally to all immigrant groups`], ans:1, exp:`The Chinese Exclusion Act was the first major U.S. federal law to restrict immigration based explicitly on nationality, barring most Chinese laborers from entering the country.` },
      { q:`Ellis Island, which operated from 1892 to 1954, served primarily as:`, ch:[`A major immigration processing station for immigrants arriving on the East Coast, particularly from Europe`,`A military base`,`A center exclusively for Asian immigration`,`A permanent detention facility for all immigrants`], ans:0, exp:`Ellis Island in New York Harbor was the primary immigration processing station for millions of immigrants, especially from Europe, arriving on the East Coast during this period.` },
      { q:`The Immigration Act of 1924 (Johnson-Reed Act) established:`, ch:[`Open immigration with no restrictions`,`National origin quotas that heavily favored immigrants from Northern and Western Europe while severely restricting others`,`Unlimited immigration from all nations equally`,`The abolition of all immigration quotas`], ans:1, exp:`The 1924 act created national-origin quotas explicitly designed to favor immigration from Northern and Western Europe while sharply restricting immigration from other regions.` },
      { q:`The Immigration and Nationality Act of 1965 significantly changed U.S. immigration policy by:`, ch:[`Reinstating strict national-origin quotas`,`Abolishing national-origin quotas and establishing a system that led to increased immigration from Asia, Latin America, and Africa`,`Banning all immigration from Europe`,`Ending immigration entirely`], ans:1, exp:`This 1965 law abolished the earlier national-origin quota system, leading to substantially increased and more diverse immigration from Asia, Latin America, and Africa in subsequent decades.` },
      { q:`Angel Island, on the West Coast, functioned similarly to Ellis Island but primarily processed:`, ch:[`European immigrants exclusively`,`Immigrants primarily from Asia, including many Chinese and Japanese immigrants, who often faced more intensive screening`,`Immigrants from South America only`,`Refugees from Canada`], ans:1, exp:`Angel Island in San Francisco Bay processed immigrants primarily from Asia, and many, particularly Chinese immigrants, faced more intensive and lengthy screening compared to European arrivals at Ellis Island.` },
      { q:`The Bracero Program (1942-1964) was established to:`, ch:[`Restrict all Mexican immigration to the U.S.`,`Allow Mexican laborers to work temporarily in U.S. agriculture and railroads, particularly during and after World War II labor shortages`,`Grant permanent U.S. citizenship automatically to all Mexican workers`,`End agricultural labor migration permanently`], ans:1, exp:`The Bracero Program permitted temporary Mexican agricultural and railroad workers to fill U.S. labor shortages, particularly during and following World War II.` },
      { q:`Which factor is commonly cited as a "push factor" driving historical waves of immigration to the United States?`, ch:[`Political or religious persecution and economic hardship in immigrants' home countries`,`Guaranteed high-paying jobs in every case`,`The complete absence of any hardship at home`,`A desire to avoid all forms of work`], ans:0, exp:`Push factors are conditions in an immigrant's home country — such as political or religious persecution and economic hardship — that motivate emigration, in contrast to "pull factors" that attract people to a destination.` },
      { q:`The term "nativism" in American immigration history refers to:`, ch:[`A movement supporting expanded immigration rights`,`Anti-immigrant sentiment and policies favoring established inhabitants over new immigrants`,`A term describing Native American tribal governance`,`Government support for refugee resettlement`], ans:1, exp:`Nativism describes a preference for established, native-born inhabitants over immigrants, often reflected in restrictive laws and anti-immigrant political movements throughout U.S. history.` },
      { q:`The Refugee Act of 1980 established:`, ch:[`A ban on all refugee admissions`,`A formal U.S. legal process and definition for admitting refugees fleeing persecution`,`The abolition of asylum protections`,`Automatic citizenship for all refugees upon arrival`], ans:1, exp:`The Refugee Act of 1980 created a systematic legal framework and definition for admitting refugees fleeing persecution, aligning U.S. law more closely with international refugee standards.` },
      { q:`Which best describes the general historical pattern of immigration to the U.S. from the late 19th to early 20th century, sometimes described as the shift from "old" to "new" immigration?`, ch:[`Immigration remained constant from the same countries throughout`,`A shift occurred from predominantly Northern and Western European immigrants to increasing numbers of Southern and Eastern European immigrants`,`All immigration during this period came from Asia`,`Immigration to the U.S. ceased entirely during this period`], ans:1, exp:`This era saw a demographic shift in immigration sources, with growing numbers arriving from Southern and Eastern Europe alongside the earlier predominance of Northern and Western European immigrants.` },
      { q:`The Immigration Reform and Control Act of 1986 notably:`, ch:[`Provided a pathway to legal status for certain undocumented immigrants already in the U.S. while also introducing sanctions for employers hiring undocumented workers`,`Ended all immigration enforcement`,`Deported all undocumented immigrants immediately`,`Eliminated the need for employer verification of work status`], ans:0, exp:`This 1986 law combined a legalization pathway for certain undocumented immigrants already residing in the U.S. with new employer sanctions for knowingly hiring undocumented workers.` },
      { q:`Which of the following best reflects a key ongoing debate in American immigration policy?`, ch:[`There is universal consensus with no disagreement on immigration policy`,`Balancing economic benefits, humanitarian concerns, border security, and integration of new immigrants involves ongoing political and social debate`,`Immigration policy has remained completely unchanged since 1776`,`Immigration is not connected to labor markets in any way`], ans:1, exp:`U.S. immigration policy debates continue to involve balancing considerations such as economic impact, humanitarian obligations, border security, and successful integration of newcomers.` },
      { q:`Statue of Liberty symbolism, especially Emma Lazarus's poem "The New Colossus," is often associated with:`, ch:[`Strict immigration restriction`,`An ideal of America as a welcoming refuge for immigrants seeking freedom and opportunity`,`Military conquest`,`Exclusively economic trade policy`], ans:1, exp:`Lazarus's poem, inscribed on the Statue of Liberty's pedestal, has become strongly associated with the ideal of America as a welcoming haven for immigrants seeking freedom and new opportunity.` },
    ]
  },
  {
    id:'ps142', cat:'Behavioral & Social Sciences', title:"Women's Suffrage & the Women's Rights Movement", diff:'Medium',
    qs:[
      { q:`The Seneca Falls Convention (1848) is widely regarded as:`, ch:[`The founding event of the U.S. civil rights movement for African Americans`,`One of the first major organized women's rights conventions in the U.S., producing the Declaration of Sentiments`,`A treaty ending a war`,`A labor union founding convention`], ans:1, exp:`Seneca Falls is widely considered one of the first major organized conventions for women's rights in the U.S., producing the influential Declaration of Sentiments.` },
      { q:`The Declaration of Sentiments, produced at Seneca Falls, was modeled after:`, ch:[`The U.S. Constitution's Bill of Rights`,`The Declaration of Independence, asserting that "all men and women are created equal"`,`The Emancipation Proclamation`,`The Federalist Papers`], ans:1, exp:`The Declaration of Sentiments deliberately echoed the structure and language of the Declaration of Independence, applying its principles of equality explicitly to women.` },
      { q:`The 19th Amendment to the U.S. Constitution, ratified in 1920, granted:`, ch:[`African American men the right to vote`,`Women the constitutional right to vote nationwide`,`Eighteen-year-olds the right to vote`,`Native Americans full citizenship`], ans:1, exp:`The 19th Amendment, ratified in 1920, prohibited denying the right to vote on the basis of sex, establishing women's suffrage nationwide.` },
      { q:`Susan B. Anthony and Elizabeth Cady Stanton are best known for:`, ch:[`Leading the abolitionist movement exclusively with no connection to women's rights`,`Prominent leadership in the 19th-century women's suffrage movement`,`Founding the American labor union movement`,`Serving as U.S. Supreme Court justices`], ans:1, exp:`Anthony and Stanton were prominent, influential leaders of the 19th-century women's suffrage movement, though both were also involved in other reform causes, including abolition.` },
      { q:`The women's suffrage movement often intersected with which other 19th-century reform movement?`, ch:[`The abolitionist movement, as many suffragists were also active in the fight against slavery`,`The temperance movement exclusively with no other overlap`,`The movement to expand slavery`,`A movement opposing all social reform`], ans:0, exp:`Many early suffragists were also active abolitionists, and the two movements were closely intertwined, though tensions over prioritization sometimes emerged between them.` },
      { q:`The "second wave" of American feminism, emerging in the 1960s-1970s, focused largely on:`, ch:[`Securing the right to vote for women`,`Broader social and legal equality issues such as workplace discrimination, reproductive rights, and gender roles`,`Ending child labor exclusively`,`Establishing women's suffrage for the first time`], ans:1, exp:`Second-wave feminism, distinct from the earlier suffrage-focused first wave, addressed broader issues including workplace discrimination, reproductive rights, and challenging traditional gender roles.` },
      { q:`Title IX, passed in 1972, is best known for:`, ch:[`Granting women the right to vote`,`Prohibiting sex-based discrimination in federally funded education programs, including school athletics`,`Establishing equal pay laws`,`Banning employment discrimination based on race`], ans:1, exp:`Title IX prohibited sex-based discrimination in any federally funded education program, significantly expanding opportunities for women and girls, notably in school athletics.` },
      { q:`The Equal Pay Act of 1963 aimed to:`, ch:[`Eliminate the gender wage gap immediately and completely`,`Require equal pay for men and women performing substantially equal work at the same establishment`,`Ban women from certain professions`,`Establish a minimum wage for the first time`], ans:1, exp:`The Equal Pay Act required that men and women receive equal pay for substantially equal work performed at the same establishment, though a wage gap has persisted due to other structural factors.` },
      { q:`Which of the following best explains why some women, particularly women of color, felt marginalized by aspects of the mainstream 19th and early 20th century suffrage movement?`, ch:[`The movement fully and equally represented all women's interests from the start`,`Some prominent suffrage leaders and organizations prioritized white women's suffrage and, at times, used racially exclusionary rhetoric or tactics`,`Women of color were not interested in voting rights`,`There was no diversity of opinion within the movement`], ans:1, exp:`Historians note that some mainstream suffrage leaders and organizations, at various points, prioritized white women's enfranchisement and, at times, employed racially exclusionary strategies, leading many Black suffragists to organize separately.` },
      { q:`The phrase "the personal is political," associated with second-wave feminism, emphasized that:`, ch:[`Personal issues have no connection to broader social and political structures`,`Individual experiences, such as in family, relationships, and the workplace, are shaped by and connected to larger systemic and political power structures`,`Politics should remain entirely separate from personal life`,`Only government elections matter for social change`], ans:1, exp:`This phrase captured the idea that seemingly private, personal experiences are shaped by and connected to broader systemic power structures, making them legitimate subjects of political analysis and action.` },
      { q:`Which amendment did some 20th-century feminists advocate for, though it was never ratified nationally, to guarantee equal legal rights regardless of sex?`, ch:[`The Equal Rights Amendment (ERA)`,`The 19th Amendment`,`The 15th Amendment`,`The 24th Amendment`], ans:0, exp:`The Equal Rights Amendment, first proposed in 1923 and passed by Congress in 1972, would have explicitly guaranteed equal legal rights regardless of sex, but it did not achieve the required number of state ratifications within its original deadlines.` },
      { q:`Wyoming Territory is notable in women's suffrage history because it:`, ch:[`Was the last state to grant women's suffrage`,`Was among the first territories or states to grant women the right to vote, in 1869`,`Banned women from voting entirely`,`Had no role in the suffrage movement`], ans:1, exp:`Wyoming Territory granted women the right to vote in 1869, making it one of the earliest jurisdictions in the U.S. to do so, well before the 19th Amendment's nationwide ratification.` },
      { q:`Which best characterizes the broader significance of the women's rights movement across its historical waves?`, ch:[`It focused on a single, narrow issue with no lasting effect on society`,`It progressively expanded legal, political, economic, and social rights and opportunities for women over more than a century`,`It ended completely after the 19th Amendment was ratified`,`It had no connection to other civil rights movements`], ans:1, exp:`Across its historical waves, the women's rights movement progressively expanded legal, political, economic, and social rights for women, continuing well beyond suffrage into areas like employment and reproductive rights.` },
    ]
  },
  {
    id:'ps143', cat:'Behavioral & Social Sciences', title:'The Labor Movement & Unions in America', diff:'Medium',
    qs:[
      { q:`The primary goal of early American labor unions in the 19th century was to:`, ch:[`Eliminate all industrial employment`,`Improve wages, working hours, and conditions for workers through collective bargaining`,`Prevent any government regulation of business`,`Replace capitalism with a fully agrarian economy`], ans:1, exp:`Early labor unions organized to collectively bargain for improved wages, shorter hours, and safer working conditions on behalf of industrial workers.` },
      { q:`The Haymarket affair (1886) in Chicago is significant in labor history because:`, ch:[`It led to the immediate abolition of the eight-hour workday movement`,`A bombing during a labor rally led to a violent confrontation and heightened public fear of the labor movement, tied partly to the push for an eight-hour workday`,`It marked the founding of the U.S. Department of Labor`,`It ended all labor unrest for decades`], ans:1, exp:`The Haymarket affair, involving a bombing at a labor rally connected to the eight-hour workday movement, led to a violent police confrontation and intensified public suspicion of organized labor.` },
      { q:`The American Federation of Labor (AFL), founded in 1886, primarily organized workers based on:`, ch:[`Skilled craft trades`,`Unskilled agricultural labor exclusively`,`Only government employees`,`Exclusively female workers`], ans:0, exp:`The AFL organized primarily around skilled craft trades, in contrast to later industrial unions that organized workers across entire industries regardless of specific craft.` },
      { q:`The Triangle Shirtwaist Factory fire (1911), which killed 146 workers, contributed to:`, ch:[`A decline in support for workplace safety regulations`,`Significant public outcry that led to new workplace safety regulations and labor reforms`,`The immediate abolition of all factories`,`No changes to labor law`], ans:1, exp:`The tragic fire, which killed many young immigrant garment workers due to unsafe conditions, generated public outrage that helped drive new workplace safety regulations and labor reforms.` },
      { q:`The National Labor Relations Act (Wagner Act) of 1935:`, ch:[`Banned labor unions entirely`,`Established workers' legal right to organize unions and engage in collective bargaining`,`Eliminated the minimum wage`,`Applied only to government workers`], ans:1, exp:`The Wagner Act established federal legal protections for private-sector workers' rights to organize unions and engage in collective bargaining with employers.` },
      { q:`The Fair Labor Standards Act of 1938 established:`, ch:[`Universal healthcare coverage`,`A federal minimum wage, restrictions on child labor, and overtime pay requirements`,`A national retirement pension system`,`A ban on labor unions`], ans:1, exp:`This landmark law established a federal minimum wage, restricted child labor, and set overtime pay requirements for many workers.` },
      { q:`A "strike," as a labor tactic, refers to:`, ch:[`Workers collectively refusing to work in order to pressure an employer to meet demands, such as higher wages`,`A management tactic to lock out workers`,`A government mandate to increase production`,`A type of employee training program`], ans:0, exp:`A strike is a collective work stoppage organized by workers to pressure an employer into meeting demands, such as better wages or working conditions.` },
      { q:`Which best describes a "closed shop" versus a "right-to-work" arrangement?`, ch:[`A closed shop requires union membership as a condition of employment, while right-to-work laws prohibit requiring union membership or dues as a condition of employment`,`Both terms mean exactly the same thing`,`Right-to-work laws mandate union membership for all workers`,`A closed shop bans unions entirely`], ans:0, exp:`A closed shop requires workers to already be union members to be hired, while right-to-work laws prohibit making union membership or dues payment a condition of employment.` },
      { q:`Union membership in the United States, as a percentage of the workforce, has generally:`, ch:[`Increased steadily and continuously since the 1950s`,`Declined significantly from its mid-20th-century peak to a much smaller share of the private-sector workforce today`,`Remained exactly constant since 1900`,`Reached 100% of all workers by the 2000s`], ans:1, exp:`Union membership as a share of the U.S. workforce has declined substantially from its mid-20th-century peak, particularly in the private sector.` },
      { q:`Cesar Chavez and Dolores Huerta are best known for:`, ch:[`Founding the AFL in the 19th century`,`Co-founding and leading the United Farm Workers union to advocate for the rights of agricultural laborers, largely Latino, in the mid-20th century`,`Leading the 1935 steel workers' strike`,`Serving as U.S. Secretary of Labor`], ans:1, exp:`Chavez and Huerta co-founded and led the United Farm Workers union, organizing largely Latino agricultural laborers to advocate for better wages and working conditions.` },
      { q:`Collective bargaining refers to the process by which:`, ch:[`Individual employees negotiate salaries alone with no union involvement`,`A union negotiates on behalf of its members with an employer over wages, hours, and working conditions`,`Employers set wages unilaterally with no worker input`,`Government sets all wages by law`], ans:1, exp:`Collective bargaining involves a union negotiating collectively with an employer on behalf of its member workers over wages, hours, and working conditions.` },
      { q:`The decline of American manufacturing jobs in recent decades has been cited as a contributing factor to:`, ch:[`A dramatic rise in union membership nationwide`,`Reduced union membership and influence in traditionally unionized industrial sectors`,`The complete elimination of the service sector`,`Universal wage increases across all industries`], ans:1, exp:`The shrinking of traditionally heavily unionized manufacturing industries has contributed to overall declines in union membership and influence in recent decades.` },
      { q:`Which of these best reflects a common critique of labor unions raised by their opponents?`, ch:[`Unions have no economic effect whatsoever`,`Unions can raise labor costs for businesses and, some argue, reduce workplace flexibility, though supporters counter this with benefits to worker wages and protections`,`Unions are required by federal law in every industry`,`Unions eliminate the need for any wage negotiation`], ans:1, exp:`Critics of unions often argue they can raise labor costs and reduce employer flexibility, while supporters counter that unions provide important benefits, such as improved wages and stronger worker protections.` },
    ]
  },
  {
    id:'ps144', cat:'Behavioral & Social Sciences', title:'Native American History: An Overview', diff:'Medium',
    qs:[
      { q:`Prior to European contact, Indigenous peoples in North America had established:`, ch:[`No organized societies or governance systems`,`Diverse societies with distinct languages, governance systems, economies, and cultures across the continent`,`A single unified nation with one language`,`Purely nomadic lifestyles with no agriculture anywhere`], ans:1, exp:`Indigenous peoples of North America developed a wide range of distinct societies prior to European contact, varying in language, governance, economy (including agriculture in many regions), and culture.` },
      { q:`The Indian Removal Act of 1830 authorized the U.S. government to:`, ch:[`Grant Native American tribes full sovereignty over their ancestral lands`,`Relocate Native American tribes from their ancestral lands in the Southeast to territory west of the Mississippi River`,`Provide U.S. citizenship to all Native Americans`,`End all conflict between settlers and tribes permanently`], ans:1, exp:`The Indian Removal Act authorized the forced relocation of Native American tribes, particularly in the Southeast, to designated territory west of the Mississippi River.` },
      { q:`The Trail of Tears refers to:`, ch:[`A hiking trail established by the National Park Service`,`The forced relocation of the Cherokee and other Southeastern tribes to Indian Territory, during which thousands died from exposure, disease, and starvation`,`A peaceful voluntary migration with no hardship`,`A World War II-era military campaign`], ans:1, exp:`The Trail of Tears was the devastating forced relocation of the Cherokee and other Southeastern tribes to Indian Territory, during which thousands died from exposure, disease, and starvation.` },
      { q:`The Dawes Act of 1887 aimed to:`, ch:[`Preserve tribal lands as collectively held territory`,`Break up tribal landholdings into individual allotments in an effort to assimilate Native Americans into individual land ownership and farming`,`Grant full self-governance to all tribes`,`Establish reservations for the first time with no prior policy`], ans:1, exp:`The Dawes Act sought to break up communally held tribal lands into individual allotments, part of a broader federal policy aimed at encouraging assimilation into individual land ownership and farming.` },
      { q:`The Battle of Little Bighorn (1876) is significant because:`, ch:[`U.S. forces achieved a decisive victory`,`Combined Native American forces, including Lakota and Cheyenne, defeated Lieutenant Colonel George Custer's forces`,`It marked the end of all conflict between the U.S. and Plains tribes`,`It occurred after the Trail of Tears in the same region`], ans:1, exp:`At Little Bighorn, combined Lakota, Cheyenne, and other allied forces defeated Custer's U.S. Army detachment, though broader conflicts with the U.S. continued afterward.` },
      { q:`The Indian Citizenship Act of 1924 granted:`, ch:[`Land ownership rights to all Native Americans`,`U.S. citizenship to Native Americans born in the United States`,`Voting rights immediately in every state with no restrictions`,`Tribal sovereignty for the first time`], ans:1, exp:`This act granted U.S. citizenship to Native Americans born within the United States, though some states continued to restrict Native voting rights for years afterward.` },
      { q:`Reservations, as established by U.S. government policy, are:`, ch:[`Areas of land historically retained or granted to Native American tribes, though often much smaller than tribes' original territories, and subject to varying degrees of tribal self-governance`,`Fully independent foreign nations with no U.S. relationship`,`Temporary camps that no longer exist today`,`Identical in size and resources to tribes' original homelands`], ans:0, exp:`Reservations are lands set aside for tribes, typically much smaller than their original territories, where tribes exercise varying degrees of self-governance while maintaining a formal relationship with the U.S. federal government.` },
      { q:`The Indian Self-Determination and Education Assistance Act of 1975 aimed to:`, ch:[`Eliminate all federal funding for tribes`,`Increase tribal control over federal programs and services affecting their communities`,`Force further assimilation policies`,`End the reservation system entirely`], ans:1, exp:`This 1975 act marked a policy shift toward increasing tribal control and self-governance over federal programs and services affecting their own communities.` },
      { q:`Boarding schools established for Native American children in the late 19th and early 20th centuries were designed, per official policy at the time, to:`, ch:[`Preserve and celebrate Native languages and cultural practices`,`Assimilate Native children into mainstream American culture, often suppressing native languages and traditions, a policy now widely recognized as deeply harmful`,`Provide vocational training with no cultural impact`,`Serve exclusively as voluntary cultural exchange programs`], ans:1, exp:`These boarding schools were designed explicitly to assimilate Native children into mainstream American culture, often through forced suppression of native languages and traditions — a policy now widely recognized as having caused significant lasting harm.` },
      { q:`Which best describes tribal sovereignty in the modern United States?`, ch:[`Federally recognized tribes have no independent governing authority`,`Federally recognized tribes retain a degree of self-governance as distinct political entities, while also interacting with federal and state law`,`Tribes function as fully independent foreign nations entirely outside U.S. law`,`Tribal sovereignty was permanently ended in 1924`], ans:1, exp:`Federally recognized tribes maintain a form of sovereign self-governance as distinct political entities, operating within a complex legal relationship involving both federal and, at times, state authority.` },
      { q:`The concept of "Manifest Destiny" in the 19th century contributed to:`, ch:[`Increased protection of Native American land rights`,`A belief that westward expansion was justified and inevitable, which contributed to displacement and conflict with Native peoples`,`A reduction in westward settlement`,`International recognition of tribal nations as sovereign states`], ans:1, exp:`Manifest Destiny, the belief that American westward expansion was justified and inevitable, contributed significantly to the displacement of and conflict with Native American peoples throughout the 19th century.` },
      { q:`Contemporary Native American activism, such as protests over land and resource issues, often centers on:`, ch:[`Concerns unrelated to historical treaties or land rights`,`Treaty rights, land and resource protection, and tribal sovereignty`,`A rejection of all forms of government interaction`,`Exclusively economic development with no cultural component`], ans:1, exp:`Modern Native American activism frequently focuses on protecting treaty rights, land and natural resources, and asserting tribal sovereignty in interactions with federal and state governments.` },
      { q:`Which of these best reflects the historical diversity of Native American societies prior to and after European contact?`, ch:[`All tribes shared one language and government structure`,`Native nations varied widely in language, social organization, economy, and governance across different regions of North America`,`Native societies had no forms of governance`,`Only Plains tribes existed in North America`], ans:1, exp:`Native American societies were remarkably diverse across regions, varying significantly in language, social organization, economic practices, and forms of governance.` },
    ]
  },
  {
    id:'ps145', cat:'Behavioral & Social Sciences', title:'US Foreign Policy Basics', diff:'Medium',
    qs:[
      { q:`The Monroe Doctrine (1823) declared that:`, ch:[`The U.S. would remain neutral in all world affairs forever`,`The Americas were closed to further European colonization and that European intervention in the Western Hemisphere would be viewed as a hostile act`,`The U.S. would colonize Europe`,`The U.S. would join European alliances`], ans:1, exp:`The Monroe Doctrine asserted that the Western Hemisphere was closed to further European colonization and that any European intervention there would be viewed as a hostile act toward the United States.` },
      { q:`"Isolationism," a recurring theme in early-to-mid 20th century U.S. foreign policy, refers to:`, ch:[`Active military intervention in every global conflict`,`A preference for avoiding political and military entanglement in foreign conflicts, particularly in Europe`,`Complete elimination of international trade`,`A policy exclusively targeting Asia`], ans:1, exp:`Isolationism describes a preference for avoiding political and military entanglements in foreign conflicts, particularly reflected in U.S. reluctance to engage in European affairs before World War II.` },
      { q:`The Truman Doctrine (1947) committed the United States to:`, ch:[`Withdraw all support from foreign nations`,`Providing political, military, and economic assistance to countries resisting communist expansion`,`Establishing colonies in Europe`,`Ending all foreign aid programs`], ans:1, exp:`The Truman Doctrine committed the U.S. to supporting countries resisting communist expansion through political, military, and economic assistance, beginning with aid to Greece and Turkey.` },
      { q:`Diplomacy, as a tool of foreign policy, primarily involves:`, ch:[`The use of military force exclusively`,`Negotiation and communication between governments to manage relationships and resolve disputes without resorting to force`,`Economic sanctions exclusively`,`Domestic legislative processes`], ans:1, exp:`Diplomacy involves negotiation and communication between governments as a means of managing international relationships and resolving disputes without resorting to military force.` },
      { q:`Economic sanctions in foreign policy are used to:`, ch:[`Reward a foreign government for desired behavior with financial incentives`,`Apply economic pressure, such as trade restrictions, on a country to influence its policies or behavior`,`Formally declare war`,`Establish new embassies`], ans:1, exp:`Sanctions apply economic pressure — such as trade restrictions or asset freezes — on a country, aiming to influence its government's policies or behavior without direct military action.` },
      { q:`A bilateral treaty differs from a multilateral treaty in that a bilateral treaty:`, ch:[`Involves only two parties or nations, while a multilateral treaty involves three or more`,`Always involves more than ten nations`,`Is not legally binding`,`Applies only to trade agreements`], ans:0, exp:`Bilateral treaties involve agreements between exactly two parties, while multilateral treaties involve three or more parties negotiating shared terms.` },
      { q:`The United States' use of "soft power" refers to influencing other nations through:`, ch:[`Military force and coercion`,`Cultural appeal, diplomacy, and economic influence rather than military coercion`,`Economic sanctions exclusively`,`Direct territorial conquest`], ans:1, exp:`Soft power describes a nation's ability to influence others through attraction and persuasion — via culture, diplomacy, and economic engagement — rather than through military coercion.` },
      { q:`NATO's principle of "collective defense," as outlined in Article 5, holds that:`, ch:[`Each member nation must act entirely independently in matters of defense`,`An armed attack against one member is considered an attack against all members`,`Only the United States is obligated to respond to threats`,`Member nations must remain neutral in all conflicts`], ans:1, exp:`Article 5 of the NATO treaty establishes the principle of collective defense, under which an armed attack against one member nation is treated as an attack against the alliance as a whole.` },
      { q:`The role of the U.S. Secretary of State in foreign policy is to:`, ch:[`Command U.S. military forces directly`,`Serve as the president's chief foreign affairs adviser and lead diplomatic relations with other nations`,`Preside over the Senate`,`Serve as head of the Federal Reserve`], ans:1, exp:`The Secretary of State serves as the president's principal foreign affairs adviser and leads U.S. diplomatic engagement with other nations and international organizations.` },
      { q:`Foreign aid, as a tool of U.S. foreign policy, is often provided to:`, ch:[`Exclusively wealthy, developed nations`,`Support economic development, humanitarian needs, or strategic partnerships with other countries`,`Fund domestic infrastructure projects`,`Replace all diplomatic relations`], ans:1, exp:`Foreign aid is often used to support economic development, address humanitarian needs, or strengthen strategic partnerships with recipient countries.` },
      { q:`The concept of "American exceptionalism" in foreign policy discourse refers to the belief that:`, ch:[`The United States has no unique role or special responsibilities in world affairs`,`The United States has a unique history, mission, or role in world affairs, distinct from other nations`,`All nations share an identical foreign policy approach`,`The U.S. should avoid any global leadership role`], ans:1, exp:`American exceptionalism refers to the belief that the United States holds a distinctive historical mission or role in world affairs, a concept that has shaped various strands of U.S. foreign policy thinking.` },
      { q:`Which branch of the U.S. government holds the constitutional power to formally declare war?`, ch:[`The President alone`,`Congress`,`The Supreme Court`,`The Department of State`], ans:1, exp:`The U.S. Constitution grants Congress the formal power to declare war, though presidents have at times deployed military forces without a formal congressional declaration.` },
      { q:`International alliances, such as NATO, are generally formed to:`, ch:[`Eliminate the need for individual national militaries`,`Provide mutual security benefits and coordinate policy among member nations facing shared threats`,`Increase conflict between member nations`,`Replace the United Nations`], ans:1, exp:`Alliances like NATO are formed to provide mutual security benefits and coordinate defense policy among member nations facing shared strategic threats.` },
    ]
  },
  {
    id:'ps146', cat:'Behavioral & Social Sciences', title:'The Middle Ages in Europe', diff:'Easy',
    qs:[
      { q:`The Middle Ages (or medieval period) in Europe is generally dated from approximately:`, ch:[`500 BCE to 1 CE`,`The fall of the Western Roman Empire (5th century CE) to around the 15th century`,`1500 CE to 1800 CE`,`1900 CE to 2000 CE`], ans:1, exp:`The medieval period is generally dated from the fall of the Western Roman Empire in the 5th century CE through roughly the 15th century, preceding the Renaissance.` },
      { q:`Feudalism, the dominant social and political system of medieval Europe, was based on:`, ch:[`A direct democracy where all citizens voted on laws`,`A hierarchical system of land-holding and mutual obligations between lords and vassals in exchange for military service and loyalty`,`A centralized empire with no local authority`,`An economy based entirely on international trade`], ans:1, exp:`Feudalism organized medieval European society around hierarchical relationships of land tenure and mutual obligation between lords and vassals, typically in exchange for military service and loyalty.` },
      { q:`Manorialism in medieval Europe refers to:`, ch:[`An urban-based commercial economic system`,`The economic system organizing rural life around a lord's manor, where peasants (serfs) worked the land in exchange for protection`,`A system of elected local government`,`A form of religious governance only`], ans:1, exp:`Manorialism organized rural medieval life around a lord's manor, where serfs worked the land in exchange for protection and the right to use a portion of the land for their own subsistence.` },
      { q:`The Catholic Church during the Middle Ages held significant influence primarily through its role in:`, ch:[`Only military affairs`,`Religious authority, education, and often political influence across much of medieval Europe`,`Manufacturing and trade exclusively`,`Scientific research alone`], ans:1, exp:`The Catholic Church wielded extensive influence during the medieval period through its religious authority, its role in education, and its frequent involvement in political affairs.` },
      { q:`The Crusades were a series of:`, ch:[`Peaceful trade missions between Europe and Asia`,`Religious military campaigns, primarily by European Christians, aimed largely at gaining control of the Holy Land`,`Purely diplomatic negotiations`,`Agricultural reforms`], ans:1, exp:`The Crusades were a series of religiously motivated military campaigns, primarily undertaken by European Christians, largely aimed at gaining or maintaining control over the Holy Land.` },
      { q:`The Black Death (bubonic plague), which struck Europe in the mid-14th century, resulted in:`, ch:[`No significant impact on European population or society`,`The death of a substantial portion of Europe's population, contributing to significant social and economic changes, including labor shortages`,`An increase in the feudal system's strength`,`A worldwide famine with no disease involved`], ans:1, exp:`The Black Death killed a substantial share of Europe's population, contributing to significant social and economic disruption, including labor shortages that helped weaken the feudal system.` },
      { q:`The Magna Carta (1215), signed in England, is significant because it:`, ch:[`Established absolute, unchecked monarchical power`,`Placed certain legal limits on the power of the English king and established principles later linked to constitutional government`,`Ended the feudal system immediately`,`Created the first English parliament with full modern powers`], ans:1, exp:`The Magna Carta placed certain legal limits on the English king's power and established principles, such as due process, that later influenced the development of constitutional government.` },
      { q:`Which best describes the social structure of medieval Europe?`, ch:[`A single social class with no hierarchy`,`A hierarchical structure typically including monarchs, nobility, clergy, and peasants/serfs`,`A purely meritocratic society`,`A system with no role for religious authority`], ans:1, exp:`Medieval European society was organized into a hierarchical structure typically including monarchs and nobility at the top, the clergy, and peasants or serfs forming the largest segment of the population.` },
      { q:`Knighthood and the code of chivalry in medieval Europe emphasized:`, ch:[`Purely economic pursuits`,`Ideals such as loyalty, honor, courage, and service to one's lord and, ideally, the protection of the weak`,`Rejection of any military service`,`Democratic elections of leaders`], ans:1, exp:`Chivalry idealized virtues such as loyalty, honor, courage, and the protection of the vulnerable, alongside a knight's obligations of military service to a lord.` },
      { q:`The Byzantine Empire, the continuation of the Eastern Roman Empire during the medieval period, was centered in:`, ch:[`Rome`,`Constantinople`,`Paris`,`London`], ans:1, exp:`The Byzantine Empire, continuing the Eastern Roman Empire after the fall of Rome in the West, was centered at Constantinople.` },
      { q:`Medieval universities, which began emerging in the 12th and 13th centuries, such as those at Bologna, Paris, and Oxford, primarily focused on:`, ch:[`Only vocational trade skills`,`Formal study of subjects such as theology, law, medicine, and the liberal arts`,`Exclusively military training`,`Agricultural techniques`], ans:1, exp:`Early European universities emphasized formal study in fields such as theology, law, medicine, and the liberal arts, establishing traditions of higher education that continue today.` },
      { q:`The Hundred Years' War (1337-1453) was fought primarily between:`, ch:[`Spain and Portugal`,`England and France, over territorial and succession disputes`,`Italy and the Byzantine Empire`,`Germany and Russia`], ans:1, exp:`The Hundred Years' War was a prolonged conflict fought primarily between England and France over territorial claims and disputes regarding succession to the French throne.` },
      { q:`The gradual decline of feudalism toward the end of the Middle Ages is often linked to factors such as:`, ch:[`A sudden and complete absence of any social change`,`The growth of towns and trade, the labor shortages after the Black Death, and the rise of centralized monarchies`,`A return to purely tribal societies`,`The disappearance of the Catholic Church`], ans:1, exp:`Feudalism's decline is linked to factors including expanding trade and urban centers, post-plague labor shortages that increased peasant bargaining power, and the growing centralization of power under monarchies.` },
    ]
  },
  {
    id:'ps147', cat:'Behavioral & Social Sciences', title:'The Islamic Golden Age', diff:'Easy',
    qs:[
      { q:`The Islamic Golden Age is generally considered to span roughly from the:`, ch:[`1st to 3rd centuries BCE`,`8th to 14th centuries CE`,`16th to 18th centuries CE`,`20th century CE`], ans:1, exp:`The Islamic Golden Age is generally dated from roughly the 8th to the 14th centuries CE, a period of significant scientific, cultural, and intellectual achievement across the Islamic world.` },
      { q:`The House of Wisdom, established in Baghdad, was significant as a center for:`, ch:[`Military training exclusively`,`The translation, preservation, and advancement of scientific, philosophical, and literary knowledge`,`Agricultural production`,`Textile manufacturing`], ans:1, exp:`The House of Wisdom in Baghdad served as a major intellectual center for translating, preserving, and advancing scientific, philosophical, and literary works from various traditions.` },
      { q:`Scholars during the Islamic Golden Age made significant advances in which of the following fields?`, ch:[`Mathematics, including algebra, astronomy, medicine, and optics`,`Only religious studies, with no scientific contributions`,`Fields entirely unrelated to science or mathematics`,`Exclusively architecture with no other advancements`], ans:0, exp:`Scholars of this era made notable contributions across multiple scientific fields, including mathematics (especially algebra), astronomy, medicine, and optics.` },
      { q:`The mathematician and scholar al-Khwarizmi is especially known for:`, ch:[`Founding modern chemistry`,`Developing foundational work in algebra, from which the term "algebra" derives`,`Discovering the circulation of blood`,`Inventing the printing press`], ans:1, exp:`Al-Khwarizmi's foundational mathematical work gave rise to the term "algebra" (from the Arabic "al-jabr"), and his name is also the root of the term "algorithm."` },
      { q:`Ibn Sina, known in the West as Avicenna, is best known for his contributions to:`, ch:[`Medieval European feudal law`,`Medicine and philosophy, notably through his influential medical text "The Canon of Medicine"`,`Musical composition`,`Naval engineering`], ans:1, exp:`Ibn Sina's "Canon of Medicine" was an influential medical text used for centuries in both the Islamic world and Europe, alongside his significant contributions to philosophy.` },
      { q:`During the Islamic Golden Age, significant works of ancient Greek philosophy and science were:`, ch:[`Entirely lost and never recovered`,`Translated into Arabic and preserved, later reintroduced to Europe partly through these translations`,`Deliberately destroyed by scholars`,`Ignored entirely by Islamic scholars`], ans:1, exp:`Islamic scholars translated and preserved numerous ancient Greek texts, which later played an important role in reintroducing classical knowledge to medieval Europe.` },
      { q:`The numeral system commonly used today, sometimes called "Arabic numerals," was:`, ch:[`Invented entirely in medieval Europe`,`Transmitted to the Islamic world from India and then spread to Europe via Islamic scholars`,`Invented by the ancient Romans`,`Never used outside of the Middle East`], ans:1, exp:`The numeral system originated in India, was adopted and refined by Islamic scholars, and subsequently spread to Europe, where it became known as "Arabic numerals."` },
      { q:`Trade routes during the Islamic Golden Age, such as those connecting the Middle East, Africa, Asia, and Europe, contributed to:`, ch:[`Complete economic isolation of the Islamic world`,`The exchange of goods, technologies, and ideas across a wide geographic area`,`A decline in urban development`,`The end of all scientific inquiry`], ans:1, exp:`Extensive trade networks facilitated the exchange of goods, technologies, and ideas across a vast area spanning the Middle East, Africa, Asia, and Europe.` },
      { q:`Which best describes the caliphates, such as the Abbasid Caliphate, that governed much of the Islamic world during this period?`, ch:[`Purely decentralized tribal groups with no central governance`,`Political and religious authorities that governed large empires and, in some periods, actively supported scholarship and the arts`,`Governments with no interest in intellectual or cultural development`,`Entities with no connection to trade or urban centers`], ans:1, exp:`Caliphates such as the Abbasid Caliphate governed large, complex empires and, particularly during periods of strong patronage, actively supported scholarship, science, and the arts.` },
      { q:`Advances in optics during the Islamic Golden Age are particularly associated with the scholar:`, ch:[`Ibn al-Haytham (Alhazen), who conducted pioneering experiments on light and vision`,`Isaac Newton`,`Galileo Galilei`,`Copernicus`], ans:0, exp:`Ibn al-Haytham conducted pioneering experimental work on light and vision, and his work on optics significantly influenced later European scientists.` },
      { q:`Islamic architecture from this period, such as mosques and palaces, is notably characterized by:`, ch:[`A complete absence of any artistic tradition`,`Intricate geometric patterns, calligraphy, and distinctive domes and arches`,`Styles identical to ancient Roman architecture with no distinct features`,`Buildings made exclusively of wood`], ans:1, exp:`Islamic architecture of this era is distinguished by intricate geometric patterns, decorative calligraphy, and characteristic domes and arches.` },
      { q:`The decline of the Islamic Golden Age is often attributed in part to factors such as:`, ch:[`A complete absence of any external pressures`,`Political fragmentation, invasions (including the Mongol invasions), and shifting trade routes`,`A sudden and total loss of all Islamic scholarship overnight`,`The rise of a single unified world government`], ans:1, exp:`Historians attribute the decline partly to political fragmentation, devastating invasions such as the Mongol conquests, and shifts in global trade routes over time.` },
      { q:`Overall, the Islamic Golden Age's legacy is significant to world history because:`, ch:[`It had no lasting influence on other civilizations`,`Its scholarly advances helped preserve and expand classical knowledge, later influencing the European Renaissance`,`It occurred entirely independently with no contact with other cultures`,`It focused solely on military conquest with no cultural or scientific contributions`], ans:1, exp:`The scholarly and scientific advances of the Islamic Golden Age helped preserve and expand upon classical knowledge, later playing an important role in influencing the European Renaissance.` },
    ]
  },
  {
    id:'ps148', cat:'Behavioral & Social Sciences', title:'African Civilizations & Kingdoms', diff:'Medium',
    qs:[
      { q:`The Kingdom of Mali, which reached its height in the 14th century, was renowned for its:`, ch:[`Isolation from international trade`,`Wealth derived largely from gold and salt trade across trans-Saharan trade routes`,`Purely agrarian, subsistence-based economy with no trade`,`Complete lack of urban centers`], ans:1, exp:`The Mali Empire's wealth was built substantially on its control of trans-Saharan trade routes, particularly in gold and salt.` },
      { q:`Mansa Musa, a famous ruler of the Mali Empire, is best known for:`, ch:[`Founding the Roman Empire`,`His extraordinarily wealthy pilgrimage to Mecca in 1324, which brought international attention to Mali's wealth`,`Leading a European crusade`,`Establishing the Aztec Empire`], ans:1, exp:`Mansa Musa's famously lavish 1324 pilgrimage to Mecca drew significant international attention to Mali's immense wealth, particularly its gold.` },
      { q:`The city of Timbuktu, part of the Mali Empire, became renowned as a center of:`, ch:[`Naval military power exclusively`,`Islamic scholarship, trade, and learning, including a significant collection of manuscripts`,`A purely nomadic settlement with no permanent structures`,`European colonial administration`], ans:1, exp:`Timbuktu became a major center of Islamic scholarship, trade, and learning, housing significant libraries and manuscript collections.` },
      { q:`The Kingdom of Aksum (in present-day Ethiopia/Eritrea) was notable for:`, ch:[`Being entirely isolated with no trade connections`,`Its significant role in trade connecting Africa, the Arabian Peninsula, and the Mediterranean world, and its early adoption of Christianity`,`A lack of any written language or currency`,`Being founded after European colonization`], ans:1, exp:`Aksum played a significant role in regional and long-distance trade networks connecting Africa, Arabia, and the Mediterranean, and it was one of the earliest states to formally adopt Christianity.` },
      { q:`Great Zimbabwe, a large stone-built complex in southern Africa, served as:`, ch:[`A colonial European fort`,`The center of a powerful trading kingdom, likely linked to regional and Indian Ocean trade networks`,`A purely religious pilgrimage site with no political function`,`A site built entirely by non-African peoples, according to modern scholarly consensus`], ans:1, exp:`Great Zimbabwe was the political and economic center of a powerful indigenous African kingdom, with strong archaeological and scholarly evidence linking it to regional and Indian Ocean trade networks.` },
      { q:`The Songhai Empire, which succeeded Mali as a major West African power, was notable for:`, ch:[`Having no connection to trans-Saharan trade`,`Becoming one of the largest empires in African history, controlling significant trade routes and cities including Timbuktu and Gao`,`A complete rejection of Islamic influence`,`A purely nomadic lifestyle with no cities`], ans:1, exp:`The Songhai Empire became one of the largest empires in African history, controlling key trans-Saharan trade routes and major cities including Timbuktu and Gao.` },
      { q:`The Bantu migrations refer to:`, ch:[`A single, brief movement of people within one region`,`A series of long-term migrations of Bantu-speaking peoples across much of sub-Saharan Africa over centuries, spreading languages, agriculture, and ironworking`,`A colonial-era European settlement pattern`,`A religious pilgrimage route`], ans:1, exp:`The Bantu migrations were a series of gradual, long-term population movements across sub-Saharan Africa over centuries, spreading Bantu languages along with agricultural and ironworking technologies.` },
      { q:`Trans-Saharan trade routes primarily connected:`, ch:[`North America and South America`,`West African kingdoms with North Africa and, through it, the wider Mediterranean and Middle Eastern world, primarily trading gold, salt, and other goods`,`Only regions within a single modern country`,`Africa exclusively with East Asia`], ans:1, exp:`Trans-Saharan trade routes linked West African kingdoms with North Africa and, by extension, the broader Mediterranean and Middle Eastern trading world, moving goods such as gold and salt.` },
      { q:`Which resource was a major driver of wealth and trade for West African kingdoms like Ghana, Mali, and Songhai?`, ch:[`Oil`,`Gold, along with salt`,`Rubber`,`Coal`], ans:1, exp:`Gold and salt were the major commodities driving the wealth and trans-Saharan trade networks of West African kingdoms such as Ghana, Mali, and Songhai.` },
      { q:`The ancient Kingdom of Kush, located south of Egypt along the Nile, is notable for:`, ch:[`Having no interaction with ancient Egypt`,`A close and complex relationship with ancient Egypt, at times ruling over Egypt itself (the 25th Dynasty)`,`Being founded in the modern era`,`Existing entirely in West Africa`], ans:1, exp:`Kush had a long, complex relationship with ancient Egypt, including a period during the 25th Dynasty when Kushite rulers governed Egypt itself.` },
      { q:`Oral tradition in many African societies historically served an important role in:`, ch:[`Preventing the transmission of any historical knowledge`,`Preserving history, genealogy, and cultural values across generations through storytelling and oral historians, such as griots`,`Replacing all forms of governance`,`Being used exclusively for entertainment with no informational value`], ans:1, exp:`Oral tradition, including specialized oral historians such as griots in West Africa, played a vital role in preserving history, genealogy, and cultural values across generations.` },
      { q:`European colonization of Africa, particularly intensifying in the late 19th century ("Scramble for Africa"), significantly disrupted:`, ch:[`Nothing, as African societies were entirely unaffected`,`Existing African political structures, economies, and social systems, often through arbitrary imposed borders and resource extraction`,`Only regions with no prior political organization`,`European economies exclusively`], ans:1, exp:`Colonization significantly disrupted existing African political, economic, and social structures, often through arbitrarily drawn borders and extensive resource extraction.` },
      { q:`Which statement best reflects the historical reality of pre-colonial African civilizations?`, ch:[`Africa had no organized states, trade networks, or cultural achievements prior to European contact`,`Africa was home to diverse, complex societies, kingdoms, and trade networks well before European colonization`,`All African societies were identical in structure and culture`,`Written language never existed anywhere in pre-colonial Africa`], ans:1, exp:`Pre-colonial Africa was home to a wide diversity of complex societies, kingdoms, and extensive trade networks, well documented through archaeology and historical records.` },
    ]
  },
  {
    id:'ps149', cat:'Behavioral & Social Sciences', title:'Asian Dynasties: China and Japan', diff:'Medium',
    qs:[
      { q:`The Tang Dynasty (618-907 CE) in China is often considered a golden age known for:`, ch:[`Cultural, economic, and territorial expansion, including flourishing arts, poetry, and international trade along the Silk Road`,`Complete isolation from foreign trade`,`A total collapse of centralized government`,`The introduction of feudalism for the first time`], ans:0, exp:`The Tang Dynasty is widely regarded as a golden age of Chinese cultural flourishing, territorial expansion, and international trade, particularly along the Silk Road.` },
      { q:`The Silk Road refers to:`, ch:[`A single road built entirely within China`,`A network of trade routes connecting China with Central Asia, the Middle East, and Europe, facilitating exchange of goods, ideas, and technologies`,`A modern highway system`,`A purely maritime trade route with no overland component`], ans:1, exp:`The Silk Road was an extensive network of overland (and some maritime) trade routes connecting China to Central Asia, the Middle East, and Europe, facilitating exchange of goods, ideas, and technology.` },
      { q:`The civil service examination system, extensively developed during Chinese dynasties (notably refined under the Tang and Song), was designed to:`, ch:[`Select government officials based on hereditary noble birth alone`,`Select officials based on merit through rigorous examinations, often testing knowledge of Confucian classics`,`Eliminate the need for any government bureaucracy`,`Restrict education entirely to the wealthy`], ans:1, exp:`The civil service examination system aimed to select government officials based on merit, testing candidates' mastery of Confucian classical texts rather than solely relying on noble birth.` },
      { q:`The Song Dynasty (960-1279 CE) is notable for technological and economic innovations, including:`, ch:[`The invention of the printing press, gunpowder-based weapons developments, and advances in a market economy`,`A complete lack of trade or economic activity`,`The abolition of the civil service examination system`,`The isolation of China from all outside contact`], ans:0, exp:`The Song Dynasty saw significant technological innovations, including printing advancements and gunpowder weapon developments, alongside a flourishing market economy.` },
      { q:`The Great Wall of China, though built and expanded over many centuries by various dynasties, was primarily constructed to:`, ch:[`Serve as a purely ceremonial structure with no defensive purpose`,`Defend against invasions and raids from northern nomadic groups`,`Facilitate international maritime trade`,`Mark territorial boundaries for internal provinces only`], ans:1, exp:`The Great Wall was built and expanded primarily as a defensive structure to protect against invasions and raids from northern nomadic groups.` },
      { q:`The Ming Dynasty (1368-1644) in China is notable for, among other things:`, ch:[`Complete rejection of any naval exploration`,`Extensive maritime voyages led by Admiral Zheng He, as well as significant construction projects like the Forbidden City`,`The introduction of Christianity as the state religion`,`A total absence of centralized imperial rule`], ans:1, exp:`The Ming Dynasty is notable for Admiral Zheng He's extensive maritime voyages and major construction projects, including the Forbidden City in Beijing.` },
      { q:`Confucianism, deeply influential in Chinese and broader East Asian history, emphasizes:`, ch:[`Individualism above all social obligations`,`Social harmony, filial piety, respect for hierarchy, and ethical governance`,`Rejection of any formal education`,`A purely materialistic worldview with no ethical component`], ans:1, exp:`Confucianism emphasizes social harmony, filial piety, respect for social hierarchy, and ethical governance, deeply shaping Chinese and broader East Asian political and social thought.` },
      { q:`Feudal Japan's social structure under the shogunate system was generally organized with which of the following holding significant political and military power?`, ch:[`Merchants at the very top, with samurai at the bottom`,`The shogun and samurai warrior class holding significant political and military power, with a rigid class structure below them`,`A purely democratic structure with elected officials`,`No distinction between social classes`], ans:1, exp:`Under the shogunate system, the shogun and the samurai warrior class held significant political and military power, presiding over a rigidly structured social hierarchy.` },
      { q:`The samurai in feudal Japan were:`, ch:[`Farmers with no military role`,`A warrior class bound by a code of conduct (bushido) emphasizing loyalty, honor, and martial skill, serving feudal lords (daimyo)`,`Merchants who controlled trade exclusively`,`Religious clergy with no military function`], ans:1, exp:`Samurai were a warrior class in feudal Japan bound by the code of bushido, emphasizing loyalty, honor, and martial skill, typically serving regional feudal lords known as daimyo.` },
      { q:`Japan's Edo period (1603-1868), under Tokugawa shogunate rule, was characterized by:`, ch:[`Constant civil war with no centralized authority`,`A long period of relative political stability enforced partly through a policy of national seclusion (sakoku) limiting foreign contact`,`Complete openness to unrestricted foreign trade and immigration`,`The abolition of the samurai class`], ans:1, exp:`The Edo period was marked by relatively long-lasting political stability under Tokugawa rule, enforced partly through the sakoku policy that significantly restricted foreign contact and trade.` },
      { q:`The examination-based bureaucratic system used in imperial China influenced neighboring societies, including:`, ch:[`No other societies in the region`,`Korea and Vietnam, which adapted similar Confucian-based civil service systems`,`Only European nations`,`Societies entirely outside of Asia`], ans:1, exp:`Neighboring societies such as Korea and Vietnam adapted similar Confucian-influenced civil service examination systems, reflecting the broader cultural influence of Chinese governance models in the region.` },
      { q:`Which best describes the significance of gunpowder's development in China?`, ch:[`It was developed for purely religious ceremonial use with no other applications`,`Its invention, originally in a Chinese alchemical context, eventually led to gunpowder weapons that spread and transformed warfare across Asia and, later, the world`,`It had no impact outside of China`,`It was invented in the 20th century`], ans:1, exp:`Gunpowder, originally developed in a Chinese alchemical context, eventually gave rise to gunpowder weapons that spread across Asia and later transformed warfare worldwide.` },
      { q:`The Meiji Restoration of 1868 in Japan marked:`, ch:[`A return to strict national isolation`,`A period of rapid modernization and industrialization following the end of the Tokugawa shogunate, ending feudal rule`,`The founding of the samurai class`,`A complete rejection of any Western technology or ideas`], ans:1, exp:`The Meiji Restoration ended the Tokugawa shogunate and feudal rule, ushering in a period of rapid modernization, industrialization, and adoption of Western technology and institutions.` },
    ]
  },
  {
    id:'ps150', cat:'Behavioral & Social Sciences', title:'The Age of Revolutions Beyond France', diff:'Medium',
    qs:[
      { q:`The Haitian Revolution (1791-1804) resulted in:`, ch:[`The reinforcement of slavery throughout the Caribbean`,`The establishment of Haiti as the first independent nation founded by formerly enslaved people, following a successful uprising against French colonial rule`,`French colonial rule being permanently strengthened`,`No lasting political change in the region`], ans:1, exp:`The Haitian Revolution culminated in Haiti's independence in 1804, making it the first nation founded by formerly enslaved people after a successful uprising against French colonial rule.` },
      { q:`Toussaint Louverture is best known as a key leader of:`, ch:[`The American Revolution`,`The Haitian Revolution, which began as a slave uprising against French colonial rule`,`The Mexican War of Independence`,`The Russian Revolution`], ans:1, exp:`Toussaint Louverture was a prominent leader of the Haitian Revolution, which began as a slave uprising against French colonial rule.` },
      { q:`Latin American independence movements in the early 19th century were significantly influenced by:`, ch:[`Enlightenment ideas and the example of the American and French revolutions, promoting concepts of liberty and self-governance`,`A desire to strengthen European colonial control`,`The complete absence of any European influence`,`A movement to restore indigenous empires exclusively`], ans:0, exp:`Latin American independence leaders were significantly influenced by Enlightenment ideas and the precedents set by the American and French revolutions, particularly concepts of liberty and self-governance.` },
      { q:`Simón Bolívar is best known for:`, ch:[`Leading independence movements that liberated several South American nations from Spanish colonial rule`,`Founding the United States`,`Leading the Haitian Revolution`,`Serving as a British monarch`], ans:0, exp:`Simón Bolívar led independence movements across several South American nations, playing a central role in liberating them from Spanish colonial rule.` },
      { q:`Mexico's War of Independence (1810-1821) resulted in:`, ch:[`Mexico remaining a Spanish colony indefinitely`,`Mexico gaining independence from Spanish colonial rule`,`The founding of the United States`,`A union between Mexico and France`], ans:1, exp:`Mexico achieved independence from Spanish colonial rule following its War of Independence, concluding in 1821.` },
      { q:`The wave of revolutions across Europe in 1848 is often associated with demands for:`, ch:[`The restoration of absolute monarchy`,`Liberal reforms, constitutional government, and nationalist self-determination in various European states`,`The elimination of all forms of government`,`A return to feudalism`], ans:1, exp:`The 1848 revolutions across Europe were largely driven by demands for liberal political reforms, constitutional governance, and nationalist aspirations for self-determination.` },
      { q:`Which factor commonly contributed to the spread of revolutionary ideas across the Atlantic World during the "Age of Revolutions," roughly the late 18th to mid-19th century?`, ch:[`Complete isolation between colonies and their mother countries`,`Enlightenment philosophy emphasizing natural rights, liberty, and self-governance, along with economic and social grievances against colonial or monarchical rule`,`A universal decline in literacy`,`The absence of any international trade or communication`], ans:1, exp:`Enlightenment ideas about natural rights and self-governance, combined with widespread economic and social grievances, helped fuel the spread of revolutionary movements across the Atlantic World during this era.` },
      { q:`The Latin American independence movements generally aimed to:`, ch:[`Strengthen European colonial administration`,`End Spanish and Portuguese colonial rule and establish independent, self-governing nations`,`Reunite with their former colonial powers permanently`,`Establish new colonies in Europe`], ans:1, exp:`These movements sought to end Spanish and Portuguese colonial control and establish new, independent, self-governing nations across Latin America.` },
      { q:`Which outcome was common to many newly independent Latin American nations in the 19th century following independence?`, ch:[`Immediate, stable democratic governance with no internal conflict`,`Ongoing political instability, including struggles over how to structure new governments, and social and economic inequalities inherited from the colonial period`,`A complete absence of any economic challenges`,`Rapid full political unification into one single nation`], ans:1, exp:`Many newly independent Latin American nations experienced significant political instability and ongoing social and economic inequalities inherited from the colonial era as they worked to establish new governing structures.` },
      { q:`The Haitian Revolution had a significant international impact by:`, ch:[`Having no effect on other nations`,`Alarming slaveholding powers and inspiring both fear and hope among enslaved and free Black populations elsewhere in the Americas`,`Ending slavery throughout the entire world immediately`,`Strengthening French colonial holdings in the Caribbean`], ans:1, exp:`The Haitian Revolution alarmed slaveholding powers across the Americas while inspiring hope among enslaved and free Black populations elsewhere, given its unprecedented success.` },
      { q:`Which best describes the role of Creole elites, people of European descent born in the Americas, in many Latin American independence movements?`, ch:[`They had no involvement in independence movements`,`They often led independence movements, seeking greater political and economic power for themselves relative to colonial administrators sent from Europe`,`They exclusively opposed all independence efforts`,`They were entirely excluded from any political roles both before and after independence`], ans:1, exp:`Creole elites often led independence movements, motivated in part by their desire for greater political and economic power relative to colonial administrators appointed directly from Europe.` },
      { q:`The term "Age of Revolutions" broadly refers to a period of:`, ch:[`Political stability with no significant upheavals`,`Widespread political upheaval and revolutionary movements across the Atlantic World from the late 18th through mid-19th centuries`,`A single revolution occurring only in France`,`A period entirely limited to Asia`], ans:1, exp:`The Age of Revolutions describes a broader period of widespread political upheaval and revolutionary movements across the Atlantic World, spanning roughly the late 18th through mid-19th centuries.` },
      { q:`Which of the following is a notable difference between the Haitian Revolution and most other revolutions of this era?`, ch:[`It is the only one that had no international influence`,`It was uniquely rooted in a successful large-scale slave uprising resulting in full abolition of slavery and independence`,`It resulted in the restoration of colonial rule`,`It took place in the 20th century`], ans:1, exp:`Unlike most other revolutions of the era, the Haitian Revolution was uniquely rooted in a successful large-scale slave uprising, resulting in both the abolition of slavery and full national independence.` },
    ]
  },
];
